window.YuhaCareComfortLibrary=Object.freeze({
 version:"20261026-1",
 license:"CC BY 4.0",
 source:"Kim et al., KMI (NAACL 2025)",
 sourceUrl:"https://github.com/hjkim811/KMI",
 licenseUrl:"https://creativecommons.org/licenses/by/4.0/",
 note:"한국어 공개 연구용 가상 상담 대화에서 발췌한 문장으로, 의학적 조언이 아닙니다.",
 quotes:[{"id":1,"text":"혼자의 시간을 존중하는 것과 타인을 배려하는 마음 사이에서 균형을 찾으려고 노력하는 과정은 중요합니다.","sourceDialogue":307,"category":"대인관계","label":"General"},{"id":2,"text":"감정을 나눠주시며 자신을 돌보려는 노력이 느껴집니다. 심리적 안정을 찾기 위해 여기까지 오신 게 용기 있으신 행동이에요.","sourceDialogue":288,"category":"대인관계","label":"Affirm"},{"id":3,"text":"감정을 소중히 여기고 이에 대한 확신을 갖게 되셨음이 마음을 가볍게 만드는 데 도움이 되었군요.","sourceDialogue":15,"category":"정신건강","label":"Affirm"},{"id":4,"text":"감정을 이해받고 상호 존중하는 관계를 지향한다는 목표를 가지고 계시네요.","sourceDialogue":250,"category":"대인관계","label":"Affirm"},{"id":5,"text":"사랑을 받고 싶은 마음은 모든 사람이 갖고 있는 자연스러운 감정입니다. 사랑을 찾는 여정에서 자신을 더 잘 이해하게 되셨을 거예요.","sourceDialogue":541,"category":"자아·성격","label":"Complex Reflection"},{"id":6,"text":"솔직하면서 자연스러운 관계를 원하시는 마음이 가치있는 변화로 이어질 수 있을 것입니다.","sourceDialogue":207,"category":"대인관계","label":"Affirm"},{"id":7,"text":"스스로의 가치를 발견하고 자신감을 회복하고자 하는 용기 내신 것, 정말 용기 있는 결정이십니다.","sourceDialogue":736,"category":"취업·진로","label":"Affirm"},{"id":8,"text":"가족과의 시간을 가치 있게 만들고자 하는 생각이 용기 있는 선택임을 알 수 있습니다.","sourceDialogue":182,"category":"정신건강","label":"Affirm"},{"id":9,"text":"개인의 정서적 경계를 설정하는 방법에 관한 연구들은 개인이 자신의 필요와 감정을 더 잘 이해하고 타인과의 관계에서 건강한 균형을 찾는데 도움이 될 수 있다고 말합니다.","sourceDialogue":379,"category":"대인관계","label":"Give Information"},{"id":10,"text":"대화에 더 자연스럽게 참여하고 싶다는 생각은 소중한 감정이네요.","sourceDialogue":291,"category":"대인관계","label":"Affirm"},{"id":11,"text":"불안감을 다루는 과정에서 본인 스스로를 격려하고 이해하는 태도가 도움이 될 것입니다.","sourceDialogue":285,"category":"대인관계","label":"General"},{"id":12,"text":"새로운 일 앞에서 스스로에게 부담을 느끼는 것은 자연스러운 반응입니다.","sourceDialogue":473,"category":"자아·성격","label":"General"},{"id":13,"text":"서로의 마음을 이해하기 위한 솔직한 대화를 준비하시는 모습이 대단히 존중스럽습니다.","sourceDialogue":339,"category":"대인관계","label":"Affirm"},{"id":14,"text":"스스로를 돌보고자 하는 마음가짐은 매우 중요한 걸음이 될 수 있습니다.","sourceDialogue":227,"category":"대인관계","label":"Affirm"},{"id":15,"text":"스스로를 이해하려는 노력은 큰 의미가 있습니다.","sourceDialogue":285,"category":"대인관계","label":"Affirm"},{"id":16,"text":"엄마에 대한 감정과 그 영향을 이해하려는 노력은 자신의 내면을 다루는데 도움이 될 것입니다.","sourceDialogue":962,"category":"가족","label":"Complex Reflection"},{"id":17,"text":"자신을 더 깊이 이해하려는 결정은 더욱 성숙한 관계로 나아가는 데 도움이 됩니다.","sourceDialogue":482,"category":"자아·성격","label":"Affirm"},{"id":18,"text":"작은 성공을 통한 긍정적인 메시지가 자신감 회복에 큰 도움이 될 것입니다.","sourceDialogue":61,"category":"정신건강","label":"Affirm"},{"id":19,"text":"감정에 솔직한 모습이 자신에 대한 이해를 높이는 데 도움이 될 수 있습니다.","sourceDialogue":981,"category":"가족","label":"Complex Reflection"},{"id":20,"text":"그 부담이 커질 때 스스로를 돌보는 방법을 찾는 것도 필요하겠네요.","sourceDialogue":680,"category":"취업·진로","label":"General"},{"id":21,"text":"대화에서 마음을 여는 방법을 찾고자 하는것은 양방향의 이해와 존중이 필요함을 아시는군요.","sourceDialogue":328,"category":"대인관계","label":"General"},{"id":22,"text":"마음을 가볍게 하기 위해 스스로 취미나 활동을 찾으려는 결심이 정말 용기 있는 행동입니다.","sourceDialogue":138,"category":"정신건강","label":"Affirm"},{"id":23,"text":"소중한 마음을 엄마께 전달하려는 노력에 대해 용기 있게 말씀해주셨군요.","sourceDialogue":49,"category":"정신건강","label":"Affirm"},{"id":24,"text":"소중한 사람들을 생각하며 자신을 변화시키려는 마음이 참 아름답습니다.","sourceDialogue":180,"category":"정신건강","label":"Affirm"},{"id":25,"text":"스스로를 되돌아보는 시간을 통해 조금씩 자신을 이해하는 데 도움을 받고 있었네요.","sourceDialogue":471,"category":"자아·성격","label":"Complex Reflection"},{"id":26,"text":"실수해도 괜찮다는 생각을 가지려고 한다니, 자신에게 더욱 관대해지려는 노력이 느껴집니다.","sourceDialogue":494,"category":"자아·성격","label":"Affirm"},{"id":27,"text":"아이들에 대한 마음을 되찾고자 하는 의지가 보이네요. 그리고 그런 의지를 여기서 말씀해주신 것도 용기있는 행동입니다.","sourceDialogue":179,"category":"정신건강","label":"Affirm"},{"id":28,"text":"이런 상황에서도 스스로를 잘 돌보려 노력하셨네요.","sourceDialogue":232,"category":"대인관계","label":"Affirm"},{"id":29,"text":"자신을 돌보고자 하는 의지를 가지고 다양한 방법을 모색하시는데, 정말 용기있으신 행동이세요.","sourceDialogue":103,"category":"정신건강","label":"Affirm"},{"id":30,"text":"자신의 감정에 집중하려는 노력이 쉽지 않은 일임을 이해합니다.","sourceDialogue":139,"category":"정신건강","label":"Affirm"},{"id":31,"text":"자신의 감정을 깊이 이해하려는 노력이 여러분에게 도움이 될 것입니다.","sourceDialogue":178,"category":"정신건강","label":"Give Information"},{"id":32,"text":"자신의 우선순위를 설정하는 것과 다른 사람을 존중하는 것 사이에서 고민하는 것은 자연스러운 일입니다.","sourceDialogue":307,"category":"대인관계","label":"General"},{"id":33,"text":"혼자 시간을 보내는 방식을 배우는 것도 상호 이해에 도움이 될 수 있겠네요.","sourceDialogue":581,"category":"자아·성격","label":"General"},{"id":34,"text":"혼자 있는 시간을 소중히 여기며 행복함을 느끼는 것에 대한 가치를 이해하고 계시군요.","sourceDialogue":341,"category":"대인관계","label":"General"},{"id":35,"text":"휴식을 통해 마음 건강을 돌보려는 인식은 무척 중요합니다.","sourceDialogue":827,"category":"학업·고시","label":"Affirm"},{"id":36,"text":"감정을 글로 표현하며 자신을 이해하려는 시도는 감정을 다루는 데 도움이 될 것입니다.","sourceDialogue":517,"category":"자아·성격","label":"Give Information"},{"id":37,"text":"감정을 존중받고자 하는 것이 본인에게 있어 매우 중요한 가치인 것을 인식하고 계시는군요.","sourceDialogue":211,"category":"대인관계","label":"Affirm"},{"id":38,"text":"경험에서 오는 부담이 무거움으로 느껴지는 것이 이해됩니다.","sourceDialogue":6,"category":"정신건강","label":"Affirm"},{"id":39,"text":"그 방법을 통해 자신의 감정과 행동에 대해 더 잘 이해하고 관리하는 데 도움을 받을 수 있을 겁니다.","sourceDialogue":523,"category":"자아·성격","label":"Give Information"},{"id":40,"text":"그런 순간에도 스스로를 돌보려는 노력이 중요합니다.","sourceDialogue":67,"category":"정신건강","label":"General"},{"id":41,"text":"대인 관계 속에서 더 원활한 소통을 원하신다는 마음이 존중받아야 합니다.","sourceDialogue":291,"category":"대인관계","label":"Affirm"},{"id":42,"text":"대인 관계에서 발생하는 갈등을 해결하는 것은 대화와 이해를 통해 가능하며, 기본적으로 상호 존중과 개방적인 소통이 필요하다는 것이 전문가들의 의견입니다.","sourceDialogue":269,"category":"대인관계","label":"Give Information"},{"id":43,"text":"마음을 기록하는 일기는 경험한 감정을 되돌아보고 이해하는 데 도움이 될 것입니다.","sourceDialogue":304,"category":"대인관계","label":"Give Information"},{"id":44,"text":"몸과 마음을 가벼워지게 하고자 취미와 활동을 찾아보려는 노력이 대단하세요.","sourceDialogue":138,"category":"정신건강","label":"Affirm"},{"id":45,"text":"사회적 상황에서 더 편안해지길 희망하는 마음이 이해됩니다.","sourceDialogue":491,"category":"자아·성격","label":"General"},{"id":46,"text":"삶을 소중히 여기고자 하는 노력은 정말 가치 있는 태도입니다.","sourceDialogue":136,"category":"정신건강","label":"Affirm"},{"id":47,"text":"서로 존중하며 진실된 마음으로 대하는 것은 의미 있는 관계를 형성하는 데 중요한 기준입니다.","sourceDialogue":201,"category":"대인관계","label":"General"},{"id":48,"text":"선택을 존중하려는 노력을 통해 조금 더 자신감을 갖고 결정을 내리실 수 있을 것 같네요.","sourceDialogue":95,"category":"정신건강","label":"General"},{"id":49,"text":"소중한 노력의 결과를 크게 기대하는 것은 자연스러운 일이에요.","sourceDialogue":132,"category":"정신건강","label":"General"},{"id":50,"text":"솔직한 대화를 통해 마음을 이해받고자 하는 노력이 관계를 개선하는 데 도움이 될 것입니다.","sourceDialogue":314,"category":"대인관계","label":"Complex Reflection"},{"id":51,"text":"스스로를 객관적으로 바라보려는 노력이 가치 있음을 인지하고 계십니다.","sourceDialogue":84,"category":"정신건강","label":"Affirm"},{"id":52,"text":"스스로를 보호하려는 시도에도 불구하고 몸이 자동적으로 반응하는 상황이 힘들어 보이네요.","sourceDialogue":533,"category":"자아·성격","label":"Complex Reflection"},{"id":53,"text":"스스로에 대한 이해와 변화를 위한 용기가 여기까지 오는 데 큰 역할을 했군요.","sourceDialogue":960,"category":"가족","label":"Complex Reflection"},{"id":54,"text":"스스로의 생각과 태도에서 변화를 시도해보려는 용기가 대단하십니다.","sourceDialogue":553,"category":"자아·성격","label":"Affirm"},{"id":55,"text":"자신을 이해하고 받아들이려는 노력을 시작하려는 마음가짐이 보이네요.","sourceDialogue":394,"category":"대인관계","label":"Affirm"},{"id":56,"text":"자신을 이해하려는 시도가 대단히 용기 있는 행동이네요.","sourceDialogue":575,"category":"자아·성격","label":"Affirm"},{"id":57,"text":"자신의 감정과 생각을 인지하는 과정 자체가 소중한 경험입니다.","sourceDialogue":591,"category":"자아·성격","label":"Affirm"},{"id":58,"text":"자신의 내면과 감정에 대해 깊게 고민하고자 하는 용기가 대단하십니다.","sourceDialogue":482,"category":"자아·성격","label":"Affirm"},{"id":59,"text":"자신의 마음을 이해하려는 노력이 결국은 슬픔을 이겨내는데 도움을 줄 수 있을 것입니다.","sourceDialogue":212,"category":"대인관계","label":"Complex Reflection"},{"id":60,"text":"자신의 만족과 행복을 먼저 생각하시려는 결정은 큰 용기를 필요로 합니다. 정말 용감한 선택이십니다.","sourceDialogue":329,"category":"대인관계","label":"Affirm"},{"id":61,"text":"저널링을 통해 자신의 감정을 탐색하고 싶어하는 결정은 참으로 소중한 과정이 될 것입니다.","sourceDialogue":134,"category":"정신건강","label":"Affirm"},{"id":62,"text":"혼자서 모든 부담을 지고 계셔서 외로움과 스트레스가 더욱 클 것 같아요.","sourceDialogue":560,"category":"자아·성격","label":"Complex Reflection"},{"id":63,"text":"활동을 통해 마음의 안정과 집중력 회복을 경험하신다니, 그 방법들이 상당히 효과적인 것 같네요.","sourceDialogue":87,"category":"정신건강","label":"Affirm"},{"id":64,"text":"가족과 본인의 감정상태에 대한 이해를 얻고자 하는 것이 상당히 중요하신가 봅니다.","sourceDialogue":963,"category":"가족","label":"Complex Reflection"},{"id":65,"text":"감정 변화를 추적하고 원인을 분석하는 것, 이것이 상황을 더 명확하게 이해하는 데 도움이 될 것입니다.","sourceDialogue":249,"category":"대인관계","label":"Give Information"},{"id":66,"text":"감정을 기록하는 일은 자신의 내면을 이해하는 데 도움이 됩니다.","sourceDialogue":261,"category":"대인관계","label":"Give Information"},{"id":67,"text":"감정을 이해하고 받아들이는 과정이 개인의 성장에 도움이 될 수 있습니다.","sourceDialogue":35,"category":"정신건강","label":"Give Information"},{"id":68,"text":"감정을 이해하려는 시도 자체가 매우 값진 과정임을 인식하고 계시네요.","sourceDialogue":178,"category":"정신건강","label":"Affirm"},{"id":69,"text":"감정을 표현해 본 것 자체로 이미 큰 용기를 내신 것 같아요.","sourceDialogue":991,"category":"가족","label":"Affirm"},{"id":70,"text":"감정의 혼란과 자기 의심 속에서도 스스로를 이해하려는 시도가 있네요.","sourceDialogue":571,"category":"자아·성격","label":"Complex Reflection"},{"id":71,"text":"감정이 동요될 때마다 기록하는 접근은 상황을 이해하고 관리하는 데 도움이 될 것입니다.","sourceDialogue":7,"category":"정신건강","label":"Give Information"},{"id":72,"text":"관계 속에서 긍정적인 방향을 모색하고자 하는 이 마음이 상황을 변화시킬 수 있는 원동력이 될 수 있겠네요.","sourceDialogue":1000,"category":"가족","label":"Affirm"},{"id":73,"text":"그 도전 앞에 섰을 때 느껴지는 불안감은 매우 자연스러운 감정입니다.","sourceDialogue":425,"category":"자아·성격","label":"Complex Reflection"},{"id":74,"text":"깊은 호흡과 혼자만의 시간을 가지려는 노력을 해보셨네요.","sourceDialogue":965,"category":"가족","label":"Affirm"},{"id":75,"text":"내면의 감정을 표현하는 것이 힘들어서 마음에 큰 부담을 가지고 계시군요.","sourceDialogue":223,"category":"대인관계","label":"Complex Reflection"},{"id":76,"text":"도움을 구하고 싶어하시는 용기가 정말 대단하십니다.","sourceDialogue":73,"category":"정신건강","label":"Affirm"},{"id":77,"text":"도움을 구하고자 하는 용기가 눈에 보입니다.","sourceDialogue":31,"category":"정신건강","label":"Affirm"},{"id":78,"text":"마음이 가벼워지는 것은 긍정적 진전을 의미하며, 스스로의 노력을 인식하게 되는 과정입니다.","sourceDialogue":129,"category":"정신건강","label":"Complex Reflection"},{"id":79,"text":"변화를 원하시는 마음이 강하신 것 같습니다. 용기 있는 태도입니다.","sourceDialogue":588,"category":"자아·성격","label":"Affirm"},{"id":80,"text":"상황에 대한 이해와 수용이 불안감을 완화시키는 데 도움이 될 수 있습니다.","sourceDialogue":285,"category":"대인관계","label":"General"},{"id":81,"text":"생각과 감정을 관리하는 방법을 배우려는 것은 발전을 위한 소중한 접근입니다.","sourceDialogue":430,"category":"자아·성격","label":"Affirm"},{"id":82,"text":"솔직한 대화를 시도해보고자 하는 결정이 의미 있는 첫걸음이 될 수 있음을 인식하신 점 대단히 용기 있는 선택입니다.","sourceDialogue":348,"category":"대인관계","label":"Affirm"},{"id":83,"text":"솔직함을 통한 이해를 구하는 과정에서도 많은 용기가 필요했겠군요.","sourceDialogue":276,"category":"대인관계","label":"Affirm"},{"id":84,"text":"스스로를 인정하고 사랑하는 방법을 배우고자 하는 노력에 충분한 가치가 있습니다.","sourceDialogue":290,"category":"대인관계","label":"Affirm"},{"id":85,"text":"아이를 위한 방법을 찾기 위해 열린 마음으로 다양한 시도를 하고 계시네요.","sourceDialogue":25,"category":"정신건강","label":"Affirm"},{"id":86,"text":"어려운 결정을 내리려 할 때 용기가 필요함을 잘 알고 계시네요.","sourceDialogue":979,"category":"가족","label":"Affirm"},{"id":87,"text":"어려운 시기를 겪고도 회복을 향한 용기를 갖고 계시군요.","sourceDialogue":115,"category":"정신건강","label":"Affirm"},{"id":88,"text":"엄마를 돌보는 일에 많은 시간과 에너지를 쏟고 계시네요.","sourceDialogue":983,"category":"가족","label":"Affirm"},{"id":89,"text":"오전 시간에 마음이 편안해지는 시간을 활용하는 건 좋은 시작입니다.","sourceDialogue":153,"category":"정신건강","label":"Affirm"},{"id":90,"text":"외로움과 우울함이 줄어들게 되길 바라시는 마음은 매우 이해가 갑니다.","sourceDialogue":192,"category":"정신건강","label":"Complex Reflection"},{"id":91,"text":"외로움을 느끼시면서도, 혼자 있는 것이 더 편안함을 찾게 되셨군요.","sourceDialogue":93,"category":"정신건강","label":"Complex Reflection"},{"id":92,"text":"용기를 내어 상황에 직면하고자 하는 계획이 여러분의 성장에 큰 도움이 될 것입니다.","sourceDialogue":501,"category":"자아·성격","label":"Affirm"},{"id":93,"text":"이전 경험을 바탕으로 스스로 해결책을 찾으려는 노력이 대단하십니다.","sourceDialogue":987,"category":"가족","label":"Affirm"},{"id":94,"text":"이해와 공감을 통해 관계의 질을 향상시키고자 하는 노력이 느껴집니다.","sourceDialogue":551,"category":"자아·성격","label":"Affirm"},{"id":95,"text":"일기를 통해 자신의 생각과 감정을 정리하려는 시도가 도움이 될 겁니다.","sourceDialogue":970,"category":"가족","label":"General"},{"id":96,"text":"자신의 감정과 생각을 솔직하게 표현하는 연습을 통해 서로에 대한 이해를 깊게 하려는 시도는 매우 가치 있는 접근법이 될 것입니다.","sourceDialogue":52,"category":"정신건강","label":"Complex Reflection"},{"id":97,"text":"자신의 노력을 인정하게 되었을 때, 마음에도 조금의 여유가 생기기 시작하는 것 같네요.","sourceDialogue":734,"category":"취업·진로","label":"Affirm"},{"id":98,"text":"자신의 생각과 감정을 이해하려는 노력이 중요한 과정입니다.","sourceDialogue":571,"category":"자아·성격","label":"General"},{"id":99,"text":"자신의 정체성을 이해하려는 노력은 결국 스스로를 더 잘 알게 되는 길이 될 거예요.","sourceDialogue":128,"category":"정신건강","label":"Complex Reflection"},{"id":100,"text":"짧은 순간들이라도 마음의 부담을 덜어주는 것에 대한 소중함을 느끼시는 거로 들리네요.","sourceDialogue":171,"category":"정신건강","label":"Complex Reflection"},{"id":101,"text":"친구들과 편안하게 지내지 못하는 상황이 스스로에게 상당히 힘들게 느껴지시겠어요.","sourceDialogue":336,"category":"대인관계","label":"Complex Reflection"},{"id":102,"text":"친구들과의 대화를 통해 다른 사람들의 감정을 관찰하고 비교하며 자신의 감정을 이해하는 데 도움을 받으셨군요.","sourceDialogue":539,"category":"자아·성격","label":"Complex Reflection"},{"id":103,"text":"친구를 향한 깊은 배려와 변화를 바라는 마음이 돋보입니다.","sourceDialogue":385,"category":"대인관계","label":"Affirm"},{"id":104,"text":"혼자 있는 시간을 가지며 자신과의 관계를 긍정적으로 만드려는 노력이 반영되었군요.","sourceDialogue":496,"category":"자아·성격","label":"Affirm"},{"id":105,"text":"혼자서 시간을 보내며 기다리는 과정 속에서 조금씩 회복해 나가고 있군요.","sourceDialogue":318,"category":"대인관계","label":"General"},{"id":106,"text":"휴식을 통해 건강을 회복하기 위한 방안을 모색하고 계시군요.","sourceDialogue":199,"category":"정신건강","label":"Complex Reflection"},{"id":107,"text":"youtube를 통해 시간을 보내는 것이 잠시나마 마음의 부담을 덜어주는 데 도움이 되었겠군요.","sourceDialogue":995,"category":"가족","label":"Complex Reflection"},{"id":108,"text":"가능성을 탐색하는 과정 자체가 스스로에 대해 더 깊이 이해할 기회가 될 수 있습니다.","sourceDialogue":183,"category":"정신건강","label":"General"},{"id":109,"text":"가족 간의 갈등이 마음에 큰 부담을 주는군요.","sourceDialogue":956,"category":"가족","label":"Complex Reflection"},{"id":110,"text":"갈등 해소 방법을 모색하려는 노력이 본인 스스로를 더 이해하려는 좋은 접근이 될 수 있겠네요.","sourceDialogue":461,"category":"자아·성격","label":"Complex Reflection"},{"id":111,"text":"감정 조절을 향한 배움에 열린 마음을 가지신 점은 높이 평가됩니다.","sourceDialogue":417,"category":"자아·성격","label":"Affirm"},{"id":112,"text":"감정과 반응을 세심하게 주시하며 상호 이해를 증진시키고자 하는 접근이 매우 중요하죠.","sourceDialogue":206,"category":"대인관계","label":"Affirm"},{"id":113,"text":"감정을 혼자서 다뤄야 한다는 부담감이 크시군요.","sourceDialogue":113,"category":"정신건강","label":"Complex Reflection"},{"id":114,"text":"감정의 부담을 덜어내려고 노력하셨다는 게 느껴져요.","sourceDialogue":154,"category":"정신건강","label":"General"},{"id":115,"text":"감정이 풍부해져서 소중한 관계에 대해 더 깊이 고민하게 되셨네요.","sourceDialogue":569,"category":"자아·성격","label":"Complex Reflection"},{"id":116,"text":"감정일기 작성을 고려하고 계시는군요, 그 접근이본인의 감정을 더 잘 이해하는 데 도움이 될 수 있겠습니다.","sourceDialogue":249,"category":"대인관계","label":"Complex Reflection"},{"id":117,"text":"같은 수준의 공감과 이해를 받기 원하는 것은 인간으로서 자연스러운 욕구이죠.","sourceDialogue":249,"category":"대인관계","label":"General"},{"id":118,"text":"개인의 자유와 사생활에 대한 존중은 중요한 가치입니다.","sourceDialogue":156,"category":"정신건강","label":"General"},{"id":119,"text":"걷기를 선택하신 점이 조금이나마 마음의 부담을 덜어주고 있을 것 같네요.","sourceDialogue":126,"category":"정신건강","label":"Complex Reflection"},{"id":120,"text":"관계를 회복하려는 의지가 강하게 느껴집니다.","sourceDialogue":311,"category":"대인관계","label":"Affirm"},{"id":121,"text":"관심을 가지려는 시도가 점점 자신감을 회복하는 데 도움이 될 것임을 느끼고 계시겠군요.","sourceDialogue":8,"category":"정신건강","label":"Complex Reflection"},{"id":122,"text":"그 노력이 본인에게 큰 의미를 가질 것입니다.","sourceDialogue":974,"category":"가족","label":"Affirm"},{"id":123,"text":"그런 두려움을 표현하기까지 용기가 많이 필요하셨을 텐데요.","sourceDialogue":491,"category":"자아·성격","label":"Affirm"},{"id":124,"text":"그런 상황에서도 스스로의 감정을 잘 알아차리고 계시네요.","sourceDialogue":279,"category":"대인관계","label":"Affirm"},{"id":125,"text":"그런 생각들을 정리하면서 스스로에 대해 깊이 이해하려고 노력하고 계시군요.","sourceDialogue":471,"category":"자아·성격","label":"General"},{"id":126,"text":"글쓰기가 마음을 표현하고 정리하는데 어느 정도 도움이 될 수 있겠네요.","sourceDialogue":987,"category":"가족","label":"General"},{"id":127,"text":"남편과의 대화에 있어 열린 마음이 필요한 부분을 인지하고 계시군요.","sourceDialogue":991,"category":"가족","label":"Affirm"},{"id":128,"text":"노력하는 과정 속에서 스스로를 조금씩 인정해 나가는 것은 값진 진전이네요.","sourceDialogue":450,"category":"자아·성격","label":"Affirm"},{"id":129,"text":"노력해온 과정 속에서 스스로를 이해하려는 시도가 중요한 역할을 하고 있네요.","sourceDialogue":135,"category":"정신건강","label":"Complex Reflection"},{"id":130,"text":"마음을 진정시키는데 도움이 되는 활동을 찾으셨다니 다행입니다.","sourceDialogue":300,"category":"대인관계","label":"Affirm"},{"id":131,"text":"받고 싶었던 배려와 이해가 없었다면 실망감이 클 것입니다.","sourceDialogue":958,"category":"가족","label":"Complex Reflection"},{"id":132,"text":"변화가 필요하다고 느끼고 그 첫걸음을 모색하고 계시군요. 용기 있는 결정입니다.","sourceDialogue":492,"category":"자아·성격","label":"Affirm"},{"id":133,"text":"변화를 위한 구체적인 방법을 고민하고 계시네요. 그런 결정에 이르게 되신 것 정말 용기 있는 일입니다.","sourceDialogue":468,"category":"자아·성격","label":"Affirm"},{"id":134,"text":"변화를 위한 시도를 계획하고 계시는군요, 이런 점들을 스스로 인지하고 계시다니 놀라워요.","sourceDialogue":486,"category":"자아·성격","label":"Affirm"},{"id":135,"text":"변화에 대한 용기를 내시는 것만으로도 의미 있는 일이 될 것입니다.","sourceDialogue":291,"category":"대인관계","label":"Affirm"},{"id":136,"text":"부담감이 커지면서 스스로에게 요구하는 것도 많아지셨을 거예요.","sourceDialogue":462,"category":"자아·성격","label":"General"},{"id":137,"text":"부담을 느끼는 상황에서도 자신의 감정을 세심하게 관찰할 수 있는 능력을 개발하고 계시는군요.","sourceDialogue":334,"category":"대인관계","label":"Affirm"},{"id":138,"text":"부러움과 부족함을 느끼며 속상해하는 감정은 매우 자연스러운 반응이에요.","sourceDialogue":26,"category":"정신건강","label":"General"},{"id":139,"text":"부정적이고 악의적인 언어 사용으로 인해 소중했던 관계의 회복을 바라고 계시는군요.","sourceDialogue":401,"category":"자아·성격","label":"Complex Reflection"},{"id":140,"text":"부정적인 반응에 대한 두려움은 변화를 추구하시는 과정에서 자연스러운 감정입니다.","sourceDialogue":468,"category":"자아·성격","label":"Complex Reflection"},{"id":141,"text":"산책이나 가벼운 운동으로 마음을 다스리고자 하는 의지가 있으시네요. 용기 내셔서 좋은 생각을 하셨습니다.","sourceDialogue":153,"category":"정신건강","label":"Affirm"},{"id":142,"text":"새로운 상황에 직면할 때 그런 감정을 경험하는 건 자연스러운 일입니다.","sourceDialogue":53,"category":"정신건강","label":"General"},{"id":143,"text":"새로운 직장에서의 도전이 몸과 마음에 부담을 주고 있다는 걸 느끼시는군요.","sourceDialogue":40,"category":"정신건강","label":"Complex Reflection"},{"id":144,"text":"생활 속에서 자신에게 의미 있는 것을 찾아가려는 노력은 매우 의미가 있어 보입니다.","sourceDialogue":574,"category":"자아·성격","label":"Affirm"},{"id":145,"text":"서로를 더 잘 이해하려는 노력을 생각하신 게 인상 깊습니다.","sourceDialogue":581,"category":"자아·성격","label":"Affirm"},{"id":146,"text":"소중한 관계를 회복하고자 하는 욕구가 있으시지만, 실질적으로 어떤 방향으로 나아가야 할지에 대한 방법을 찾지 못하고 계신 상황이시군요.","sourceDialogue":401,"category":"자아·성격","label":"Complex Reflection"},{"id":147,"text":"소통 방식에 대한 탐색은 자신과 타인을 이해하는 과정에 많은 도움이 되실 거예요.","sourceDialogue":265,"category":"대인관계","label":"General"},{"id":148,"text":"솔직하게 자신의 감정과 생각을 드러낼 때 다른 사람의 말에 귀 기울이는 태도 역시 자연스럽게 발전할 것입니다.","sourceDialogue":311,"category":"대인관계","label":"General"},{"id":149,"text":"솔직한 감정 인정은 자신을 이해하는 데 중요한 발걸음이 될 수 있습니다.","sourceDialogue":578,"category":"자아·성격","label":"General"},{"id":150,"text":"솔직한 소통과 이해의 중요성을 알고 계시네요.","sourceDialogue":972,"category":"가족","label":"Affirm"},{"id":151,"text":"스스로 이해하려는 노력이 자아 인식을 높이는 중요한 발판이 될 겁니다.","sourceDialogue":128,"category":"정신건강","label":"Complex Reflection"},{"id":152,"text":"스스로를 탐색하려는 진지한 노력이 큰 발전으로 이어질 것입니다.","sourceDialogue":482,"category":"자아·성격","label":"Affirm"},{"id":153,"text":"스스로에 대한 깊은 이해를 바탕으로 할 수 있는 변화를 고민하시는군요.","sourceDialogue":451,"category":"자아·성격","label":"Complex Reflection"},{"id":154,"text":"스스로의 단점을 인식하는 과정에서 두려움을 느끼는 것은 매우 자연스러운 일입니다.","sourceDialogue":427,"category":"자아·성격","label":"Complex Reflection"},{"id":155,"text":"시간을 통해 여유를 갖고 자신을 위로하려는 생각이 현재 상황을 이해하고 받아들이는 첫걸음이 될 수 있겠네요.","sourceDialogue":213,"category":"대인관계","label":"Complex Reflection"},{"id":156,"text":"실수에 대한 두려움이 휴식마저도 힘들게 하고 있군요.","sourceDialogue":61,"category":"정신건강","label":"Complex Reflection"},{"id":157,"text":"심리적 건강을 위해 전문가의 도움을 모색하는 것도 건강한 회복 과정의 일부입니다.","sourceDialogue":739,"category":"취업·진로","label":"Affirm"},{"id":158,"text":"아이의 진정한 평안과 자신감을 위해 지속적으로 힘쓰시는 모습이 감동적이네요.","sourceDialogue":25,"category":"정신건강","label":"Affirm"},{"id":159,"text":"오빠를 향한 깊은 이해와 배려가 그 결정의 밑바탕에 있네요.","sourceDialogue":968,"category":"가족","label":"Complex Reflection"},{"id":160,"text":"이런 걱정이 마음을 사로잡고 있는 상태에서도 스스로를 돌아볼 수 있는 시간을 가지셨군요.","sourceDialogue":574,"category":"자아·성격","label":"Affirm"},{"id":161,"text":"인간 관계에서 상호 작용의 양상을 변화시키기 위해서는 자신의 감정이나 기대를 표현하는 방법을 다양화하는 것이 도움이 될 수 있습니다.","sourceDialogue":364,"category":"대인관계","label":"Give Information"},{"id":162,"text":"자신감을 갖고 감정을 표현하는 사람이 되고자하는 욕구는 매우 자연스러운 과정입니다.","sourceDialogue":320,"category":"대인관계","label":"General"},{"id":163,"text":"자신감을 높이고 존중을 받고자 하는 마음이 강하게 드러나는군요.","sourceDialogue":592,"category":"자아·성격","label":"General"},{"id":164,"text":"자신에게 변화를 가져오기 위해 필요한 단계들을 인식하고 그 길을 걷기로 결심하신 것이 존경스럽습니다.","sourceDialogue":188,"category":"정신건강","label":"Affirm"},{"id":165,"text":"자신을 더 깊이 이해하고자 하는 욕구를 갖고 계시군요, 정말 중요한 과정 거치고 계십니다.","sourceDialogue":128,"category":"정신건강","label":"Affirm"},{"id":166,"text":"자신을 더 깊이 이해함으로써 사회에서의 본인의 당당함을 회복하고자 하시는군요.","sourceDialogue":413,"category":"자아·성격","label":"Complex Reflection"},{"id":167,"text":"자신을 이해하는 과정이 여러 모로 의미 있고 중요할 거라 생각합니다.","sourceDialogue":192,"category":"정신건강","label":"General"},{"id":168,"text":"자신을 이해하려는 노력이 관계를 건강하게 만드는 데 중요한 역할을 할 수 있습니다.","sourceDialogue":482,"category":"자아·성격","label":"General"},{"id":169,"text":"자신을 존중하는 마음이 갖는 의미를 깨닫고 계시군요.","sourceDialogue":244,"category":"대인관계","label":"Complex Reflection"},{"id":170,"text":"자신의 감정을 중요하게 여기는 것은 크게 의미가 있는 일입니다.","sourceDialogue":216,"category":"대인관계","label":"Affirm"},{"id":171,"text":"자신의 진솔한 마음을 나누고 싶어하는 용기를 가지고 계시군요.","sourceDialogue":418,"category":"자아·성격","label":"Affirm"},{"id":172,"text":"자신의 진정한 관심사와 열정을 이해하려는 노력은 매우 의미 있는 과정입니다.","sourceDialogue":726,"category":"취업·진로","label":"Affirm"},{"id":173,"text":"재정적 여유가 정신적인 부담으로 다가오고 있네요.","sourceDialogue":130,"category":"정신건강","label":"Complex Reflection"},{"id":174,"text":"조급해하지 않고 천천히 나아가겠다는 자세는 매우 현명하신 결정입니다.","sourceDialogue":118,"category":"정신건강","label":"Affirm"},{"id":175,"text":"주변 사람들과의 교류를 위해 노력하시려는 의지가 보여 정말 용기 있으신 선택입니다.","sourceDialogue":351,"category":"대인관계","label":"Affirm"},{"id":176,"text":"진짜 감정을 이해하고자 하는 욕구는 자기 자신을 더 잘 알고 싶은 마음에서 비롯된 것이군요.","sourceDialogue":446,"category":"자아·성격","label":"Complex Reflection"},{"id":177,"text":"책이나 음악을 통해 침착함을 느끼는 것은 자기 자신을 이해하는 데 도움이 되었을 거예요.","sourceDialogue":589,"category":"자아·성격","label":"Complex Reflection"},{"id":178,"text":"패턴을 이해하고 개선 방안을 고민하는 건 자기 발전의 중요한 부분이 될 거예요.","sourceDialogue":134,"category":"정신건강","label":"Affirm"},{"id":179,"text":"가장 의지하고 싶은 분으로부터 이해받지 못하시니 더욱 큰 부담감을 느끼고 계시겠군요.","sourceDialogue":982,"category":"가족","label":"Complex Reflection"},{"id":180,"text":"가족 간의 문제는 종종 마음에 큰 부담을 줄 수 있습니다.","sourceDialogue":506,"category":"자아·성격","label":"General"},{"id":181,"text":"갈등을 해결하기 위해 대화를 선택한 것은 용기 있는 결정입니다.","sourceDialogue":309,"category":"대인관계","label":"Affirm"},{"id":182,"text":"감사함을 느끼고자 하는 마음은 매우 소중한 발전으로 이어질 수 있습니다.","sourceDialogue":152,"category":"정신건강","label":"General"},{"id":183,"text":"감정 조절 능력이 일상에 긍정적인 영향을 줄 것이라는 기대는 매우 자연스러운 생각입니다.","sourceDialogue":192,"category":"정신건강","label":"Complex Reflection"},{"id":184,"text":"감정 조절 방법을 배우고자 하는 본인의 의지가 성장의 길로 이끌고 있네요.","sourceDialogue":965,"category":"가족","label":"Affirm"},{"id":185,"text":"감정들과 마주하고자 하는 용기를 가지고 계시군요.","sourceDialogue":486,"category":"자아·성격","label":"Affirm"},{"id":186,"text":"감정을 드러내는 것에 대한 거부감이 있으신 것이 자신을 더 깊이 이해하고자 하는 욕구로 이어지고 있네요.","sourceDialogue":423,"category":"자아·성격","label":"Complex Reflection"},{"id":187,"text":"감정을 자유롭게 표현하고자 하는 과정을 통해 자신감을 얻으시려는 모습이 보기 좋습니다.","sourceDialogue":532,"category":"자아·성격","label":"Affirm"},{"id":188,"text":"감정을 해결하고자 하는 구체적인 탐색을 시작하려는 의지가 보입니다.","sourceDialogue":970,"category":"가족","label":"Affirm"},{"id":189,"text":"감정의 원인을 탐색하는 것이 해답을 찾는 데 도움이 될 것입니다.","sourceDialogue":571,"category":"자아·성격","label":"General"},{"id":190,"text":"개인의 감정과 생각을 이해하는 것은 자기 자신에 대한 깊은 이해로 이어지며, 이는 자아성찰과 개인적 발달에 기여할 수 있습니다.","sourceDialogue":35,"category":"정신건강","label":"Give Information"},{"id":191,"text":"계속되는 생각으로 마음의 여유를 찾기 어려웠겠어요.","sourceDialogue":17,"category":"정신건강","label":"Complex Reflection"},{"id":192,"text":"계획에 차질이 생겼을 때 불안함이 커지는 건 자연스러운 반응입니다.","sourceDialogue":67,"category":"정신건강","label":"Complex Reflection"},{"id":193,"text":"과거의 경험에 대한 여러 생각이 현재의 상황을 이해하는 데 도움을 줄 수도 있겠네요.","sourceDialogue":281,"category":"대인관계","label":"General"},{"id":194,"text":"관계 속에서 자신의 감정을 드러내는 것이 힘들어지고 있다고 느끼시는군요.","sourceDialogue":474,"category":"자아·성격","label":"Complex Reflection"},{"id":195,"text":"그러셨군요. 우울함과 불안함을 경험하는 것은 살아가면서 어려움을 겪을 때 자연스러운 과정일 수 있습니다.","sourceDialogue":532,"category":"자아·성격","label":"General"},{"id":196,"text":"그런 느낌이 들 때 스스로를 답답해하고 괴롭힐 필요는 없습니다.","sourceDialogue":116,"category":"정신건강","label":"General"},{"id":197,"text":"그런 상황에서 화가 나셨을 때의 감정을 잘 표현해 주셨네요.","sourceDialogue":965,"category":"가족","label":"Affirm"},{"id":198,"text":"그럼 지금껏 말씀하신 고민을 해결하기 위해 스스로 자각하게 되신 거네요.","sourceDialogue":995,"category":"가족","label":"General"},{"id":199,"text":"기록을 통해 생각과 감정을 정리하고자 하신다니, 그 방법이 도움이 될 것 같습니다.","sourceDialogue":411,"category":"자아·성격","label":"General"},{"id":200,"text":"나이가 들어가면서 몸의 변화와 시간을 소중히 여기는 마음 사이에서 갈등을 겪고 계시네요.","sourceDialogue":629,"category":"취업·진로","label":"Complex Reflection"},{"id":201,"text":"남의 시선보다 자신의 감정과 건강을 돌보는 것에 대해서 이제 생각하고 계신 것 같습니다.","sourceDialogue":358,"category":"대인관계","label":"Complex Reflection"},{"id":202,"text":"남의 시선에 대해 생각하면서 자신을 돌보는 시간에 대해서도 고민이 많으시겠습니다.","sourceDialogue":358,"category":"대인관계","label":"General"},{"id":203,"text":"노력하는 과정 자체가 이미 가족에게 좋은 영향을 줄 것입니다.","sourceDialogue":182,"category":"정신건강","label":"Affirm"},{"id":204,"text":"더 행복해지길 원하는 당신의 바람이 잘 드러나고 있습니다. 상호 존중을 목표로 삼는 것은 매우 성숙한 접근방식입니다.","sourceDialogue":250,"category":"대인관계","label":"Affirm"},{"id":205,"text":"도움을 받아 더 나은 방향으로 나아가고자 하는 의지가 있으신 것, 정말 중요한 걸음이라고 생각합니다.","sourceDialogue":67,"category":"정신건강","label":"Affirm"},{"id":206,"text":"따뜻한 차도 마시고 책도 읽어보는 것, 스스로를 위로하고 긴장을 완화시키려는 방법을 시도해보신다니 대단히 중요한 발걸음이 될 것입니다.","sourceDialogue":193,"category":"정신건강","label":"Affirm"},{"id":207,"text":"마음의 안정을 찾기 위해 노력하고 계신 걸로 들립니다.","sourceDialogue":180,"category":"정신건강","label":"Affirm"},{"id":208,"text":"마음의 안정을 찾으시려는 노력이 느껴집니다.","sourceDialogue":133,"category":"정신건강","label":"Affirm"},{"id":209,"text":"벽을 세워 안전함을 추구하시면서 느끼는 외로움도 상당히 힘들게 하시는군요.","sourceDialogue":293,"category":"대인관계","label":"Complex Reflection"},{"id":210,"text":"변화를 느끼시는 과정에서 두려움이 줄어들고 있음을 발견하시는 것, 정말로 의미 있는 일입니다.","sourceDialogue":168,"category":"정신건강","label":"Affirm"},{"id":211,"text":"변화를 위한 작은 시도를 시작해보고자 하는 용기가 대단하시네요.","sourceDialogue":402,"category":"자아·성격","label":"Affirm"},{"id":212,"text":"변화를 위해 노력하시는 모습이 인상 깊습니다.","sourceDialogue":994,"category":"가족","label":"Affirm"},{"id":213,"text":"변화를 향한 의지를 표현해주신 것, 정말 용기 있으신 일입니다.","sourceDialogue":90,"category":"정신건강","label":"Affirm"},{"id":214,"text":"변화를 향한 첫걸음으로 스스로를 돌아보고 결정을 내리셨군요.","sourceDialogue":443,"category":"자아·성격","label":"Affirm"},{"id":215,"text":"변화하는 과정 속에서 걱정이 생기는 것은 자연스러운 일이에요.","sourceDialogue":546,"category":"자아·성격","label":"General"},{"id":216,"text":"본인을 긍정적으로 바라보려는 노력을 생각하시는 건 매우 의미 있는 일입니다.","sourceDialogue":7,"category":"정신건강","label":"Affirm"},{"id":217,"text":"분리하고자 하는 마음이 있음에도 불구하고, 상대방이 붙잡을 때 죄책감과 힘든 감정에 휩싸이시는군요.","sourceDialogue":301,"category":"대인관계","label":"Complex Reflection"},{"id":218,"text":"불안함 속에서도 앞으로 나아가려는 용기를 내고 계시군요.","sourceDialogue":480,"category":"자아·성격","label":"Affirm"},{"id":219,"text":"사회적 관계를 통해 마음의 안정을 찾고자 하는 생각도 긍정적인 접근이 될 수 있겠네요.","sourceDialogue":521,"category":"자아·성격","label":"Affirm"},{"id":220,"text":"상실감과 함께 자신을 향해 느끼시는 죄책감도 상당히 부담스러우실 것 같군요.","sourceDialogue":305,"category":"대인관계","label":"Complex Reflection"},{"id":221,"text":"상호 이해와 존중을 바탕으로 문제 해결을 추구하는 접근 방식이 잘 작용할 것 같습니다.","sourceDialogue":969,"category":"가족","label":"Give Information"},{"id":222,"text":"상황에 대한 이해가 깊어짐으로써 해결책을 모색하는 데도 도움이 될 수 있습니다.","sourceDialogue":355,"category":"대인관계","label":"General"},{"id":223,"text":"상황을 변화시키고자 하는 의지를 가지고 계시는군요. 이는 매우 중요한 첫걸음입니다. 상태를 인식하고 변화를 추구하는 것 자체가 큰 가치가 있습니다.","sourceDialogue":962,"category":"가족","label":"Affirm"},{"id":224,"text":"새로운 분야에 도전한다는 것이 정말 쉽지 않은 과정임을 이해합니다.","sourceDialogue":129,"category":"정신건강","label":"Affirm"},{"id":225,"text":"새로운 사람을 만나는 것이 크게 부담스러웠고, 그렇기 때문에 스스로를 관계에서 멀어지게 만드는 상황에 이르렀네요.","sourceDialogue":325,"category":"대인관계","label":"Complex Reflection"},{"id":226,"text":"서로의 입장을 이해하려는 노력이 결국 관계를 더욱 돈독하게 만들 수 있겠네요.","sourceDialogue":972,"category":"가족","label":"Complex Reflection"},{"id":227,"text":"성인이 되어서 대인관계에 대한 기대치가 낮아진 것은 자연스러운 변화일 수 있어요.","sourceDialogue":263,"category":"대인관계","label":"General"},{"id":228,"text":"소통을 통한 변화를 모색하고 계시군요. 용기 있는 시도입니다.","sourceDialogue":976,"category":"가족","label":"Affirm"},{"id":229,"text":"소통의 방식과 상대방에 대한 배려를 중요하게 생각하는 귀하의 가치가 명확하군요.","sourceDialogue":255,"category":"대인관계","label":"Affirm"},{"id":230,"text":"솔직하게 자신의 걱정을 표현할 수 있는 용기가 있다는 것이 인상 깊네요.","sourceDialogue":472,"category":"자아·성격","label":"Affirm"},{"id":231,"text":"솔직한 고민을 나누는 과정이 감정을 표현하는 능력을 키우는 데 도움이 될 거라 생각됩니다.","sourceDialogue":320,"category":"대인관계","label":"General"},{"id":232,"text":"숨을 깊게 쉬며 침착하려는 노력은 마음을 다스리는 데 도움이 됩니다.","sourceDialogue":540,"category":"자아·성격","label":"Give Information"},{"id":233,"text":"스스로 결정을 내리기 위해 필요한 것을 배우고자 하는 의지가 큰 첫걸음이 될 것입니다.","sourceDialogue":421,"category":"자아·성격","label":"General"},{"id":234,"text":"스스로 해결하려는 시도 후에도 변화가 필요하다고 느끼신 거네요.","sourceDialogue":154,"category":"정신건강","label":"Complex Reflection"},{"id":235,"text":"스스로를 긍정적으로 바라보고자 하는 의지가 강해 보이네요.","sourceDialogue":505,"category":"자아·성격","label":"Affirm"},{"id":236,"text":"스스로를 돌보는 것의 중요성을 인지하며 해결의 실마리를 찾으려고 하시는군요.","sourceDialogue":22,"category":"정신건강","label":"Complex Reflection"},{"id":237,"text":"스스로를 돌보지 못하고 있다고 걱정되시는군요.","sourceDialogue":10,"category":"정신건강","label":"Complex Reflection"},{"id":238,"text":"스스로의 가치를 인지하고자 하는 여정에 대한 고민이 많으셨군요.","sourceDialogue":505,"category":"자아·성격","label":"General"},{"id":239,"text":"스스로의 행복과 충만함을 찾으려는 의지가 어려움 속에서도 빛나고 있네요.","sourceDialogue":581,"category":"자아·성격","label":"Affirm"},{"id":240,"text":"아이의 불편함과 걱정거리에 대해 이야기해보고자 하는 접근은 매우 생산적입니다.","sourceDialogue":89,"category":"정신건강","label":"Affirm"},{"id":241,"text":"압박감이 너무 커지면 자연스럽게 회피하고자 하는 마음이 들기도 하지요.","sourceDialogue":117,"category":"정신건강","label":"Complex Reflection"},{"id":242,"text":"어려운 상황 속에서도 변화를 추구하려는 용기를 나타내셨네요. 정말 대단하십니다.","sourceDialogue":484,"category":"자아·성격","label":"Affirm"},{"id":243,"text":"어려움 속에서도 변화를 추구하시려는 용기가 보기 좋습니다.","sourceDialogue":537,"category":"자아·성격","label":"Affirm"},{"id":244,"text":"어려움에도 불구하고 자신의 상황을 개선하고자 하는 마음이 엿보이네요.","sourceDialogue":447,"category":"자아·성격","label":"Affirm"},{"id":245,"text":"오빠와의 관계를 개선하려는 노력이 느껴집니다.","sourceDialogue":968,"category":"가족","label":"Affirm"},{"id":246,"text":"이런 상황에서 불안함을 느끼는 것은 자연스러운 반응입니다.","sourceDialogue":322,"category":"대인관계","label":"General"},{"id":247,"text":"이해도와 흥미를 바탕으로 선택했다는 것, 그 자체로도 중요한 의미를 가지고 있군요.","sourceDialogue":673,"category":"취업·진로","label":"Affirm"},{"id":248,"text":"자신감을 찾고 가족에게 긍정적인 영향을 주고자 하는 의지가 대단하십니다.","sourceDialogue":182,"category":"정신건강","label":"Affirm"},{"id":249,"text":"자신과 타인을 위해 감정과 생각을 솔직히 표현하려는 노력을 하고 계시군요.","sourceDialogue":474,"category":"자아·성격","label":"Affirm"},{"id":250,"text":"자신에 대한 의문을 갖는 것은 성장하는 과정에서 자연스러운 일입니다.","sourceDialogue":174,"category":"정신건강","label":"General"},{"id":251,"text":"자신에게 다정함을 베풀고자 하는 생각이 매우 소중합니다.","sourceDialogue":227,"category":"대인관계","label":"Affirm"},{"id":252,"text":"자신에게 맞는 길을 찾아 나아가기 위한 본인만의 기준을 세우려는 시도는 대단히 의미 있는 일입니다.","sourceDialogue":403,"category":"자아·성격","label":"Affirm"},{"id":253,"text":"자신을 소중히 여기고자 하는 이런 생각은 정말 중요한 발견입니다.","sourceDialogue":215,"category":"대인관계","label":"Affirm"},{"id":254,"text":"자신을 이해하려는 노력을 통해 자신의 감정과 반응에 대한 깊은 인식을 얻을 수 있겠네요.","sourceDialogue":243,"category":"대인관계","label":"Complex Reflection"},{"id":255,"text":"자신의 감정과 행동을 이해하기 어려워하고 계시네요.","sourceDialogue":492,"category":"자아·성격","label":"Complex Reflection"},{"id":256,"text":"자신의 감정을 제대로 다루기 위한 방법을 찾고자 하는 마음이 참 중요하네요.","sourceDialogue":85,"category":"정신건강","label":"General"},{"id":257,"text":"자신의 마음을 진정시키려고 관심 분야를 찾으려는 노력을 하셨네요. 이런 모습이 정말 용기 있습니다.","sourceDialogue":797,"category":"취업·진로","label":"Affirm"},{"id":258,"text":"자신의 상황을 개선하고자 하는 의지를 보여주셨네요. 용기 있는 결정입니다.","sourceDialogue":60,"category":"정신건강","label":"Affirm"},{"id":259,"text":"전문가의 도움을 통해 해결 방향을 설정하려는 결정이 현명합니다.","sourceDialogue":188,"category":"정신건강","label":"Affirm"},{"id":260,"text":"조금씩 나아지길 바라는 마음은 변화를 향한 중요한 첫걸음입니다.","sourceDialogue":98,"category":"정신건강","label":"Affirm"},{"id":261,"text":"좋아하는 일들을 하기 위해 노력하고자 하는 마음이 있으시네요.","sourceDialogue":526,"category":"자아·성격","label":"Affirm"},{"id":262,"text":"지금까지 혼자 해결하려 했던 방식을 재고하려는 시도 자체가 중요한 발전입니다.","sourceDialogue":427,"category":"자아·성격","label":"Affirm"},{"id":263,"text":"직면한 어려움을 통해 스스로에 대한 이해를 높이고자 하는 모습이 엿보입니다.","sourceDialogue":31,"category":"정신건강","label":"Complex Reflection"},{"id":264,"text":"타인에 대한 배려와 책임감이 강하신 것 같네요.","sourceDialogue":593,"category":"자아·성격","label":"Affirm"},{"id":265,"text":"타인의 부정적인 감정은 자신을 더욱 힘들게 할 수 있습니다.","sourceDialogue":287,"category":"대인관계","label":"General"},{"id":266,"text":"타인의 시선과 반응에 대해 과도하게 반응하시며 스스로를 지치게 느끼시는군요.","sourceDialogue":523,"category":"자아·성격","label":"Complex Reflection"},{"id":267,"text":"특정한 순간에 강한 감정이 몰려오는 이유를 이해하려는 시도가 중요합니다.","sourceDialogue":123,"category":"정신건강","label":"General"},{"id":268,"text":"활발한 경청과 관련된 연습, 예를 들어 비판하지 않고 상대방의 말을 반영하는 연습은 대화 속에서 자연스러움을 높이는 데 도움이 될 수 있습니다.","sourceDialogue":265,"category":"대인관계","label":"Give Information"},{"id":269,"text":"회복 과정에서 방향을 정하는 것이 순탄하지 않을 수 있습니다.","sourceDialogue":958,"category":"가족","label":"General"},{"id":270,"text":"가까운 사람들의 이해를 받지 못함으로써 느껴지는 외로움과 어려움이 깊으셨군요.","sourceDialogue":177,"category":"정신건강","label":"Complex Reflection"},{"id":271,"text":"가까운 사람이 잘되길 바라는 마음이 크시군요.","sourceDialogue":953,"category":"가족","label":"Affirm"},{"id":272,"text":"가족 간의 갈등으로 마음이 많이 무거우셨겠어요.","sourceDialogue":985,"category":"가족","label":"Complex Reflection"},{"id":273,"text":"가족 모임이 큰 부담으로 다가오고 계시는군요.","sourceDialogue":988,"category":"가족","label":"Complex Reflection"},{"id":274,"text":"가족과의 대화가 마음에 여러 감정을 일으켰군요.","sourceDialogue":263,"category":"대인관계","label":"General"},{"id":275,"text":"가족들의 기대에 부응하고 싶은 마음과 그 기대에 미치지 못할까 봐 느끼는 압박감 사이에서 고민하고 계시네요.","sourceDialogue":186,"category":"정신건강","label":"Complex Reflection"},{"id":276,"text":"간단한 스케치부터 시작해보고자 하는 용기가 대단하십니다.","sourceDialogue":116,"category":"정신건강","label":"Affirm"},{"id":277,"text":"감정 일기를 통해 자신의 감정을 세심하게 관찰하고 이해하는 과정이 위안이 되기도 합니다.","sourceDialogue":262,"category":"대인관계","label":"Give Information"},{"id":278,"text":"감정과 생각을 표현하는 데 어려움이 있을 경우, 정서 기록법과 같은 기록 활동이나 상호작용 기반의 대화 기술 훈련이 도움이 될 수 있습니다.","sourceDialogue":28,"category":"정신건강","label":"Give Information"},{"id":279,"text":"감정에 대해 솔직함은 때로 우리가 자신을 더 잘 알게 만드는 길입니다.","sourceDialogue":981,"category":"가족","label":"General"},{"id":280,"text":"감정에 솔직해지고 싶은 마음이 드는 것은 중요한 변화로 이어질 수 있습니다.","sourceDialogue":490,"category":"자아·성격","label":"Complex Reflection"},{"id":281,"text":"감정에 주의를 기울여 나가려는 결정을 내리셨네요. 올바른 방향으로 나아가고 계십니다.","sourceDialogue":15,"category":"정신건강","label":"Affirm"},{"id":282,"text":"감정을 분석하고 파악하는 방법을 배우고 싶다는 생각이 지금의 어려움을 해결하는 데 도움이 될 수 있겠네요.","sourceDialogue":5,"category":"정신건강","label":"Complex Reflection"},{"id":283,"text":"감정을 인지하고 이해하는 과정에서 시작되는군요.","sourceDialogue":134,"category":"정신건강","label":"General"},{"id":284,"text":"감정을 잘 표현하시고 상황을 개선하고자 하는 의지를 보여주셨습니다.","sourceDialogue":86,"category":"정신건강","label":"Affirm"},{"id":285,"text":"감정을 파악하려는 의지를 가지고 계시는 건 긍정적인 자세입니다.","sourceDialogue":438,"category":"자아·성격","label":"Affirm"},{"id":286,"text":"감정을 피하는 것이 관계 형성에 어려움을 만들고 있다는 것을 인식하신 것은 중요한 발견입니다.","sourceDialogue":261,"category":"대인관계","label":"Affirm"},{"id":287,"text":"감정의 원인을 이해하려는 시도는 문제 해결 과정에서 매우 중요한 부분임을 인식하고 계시네요.","sourceDialogue":238,"category":"대인관계","label":"Affirm"},{"id":288,"text":"감정이나 생각을 정리하는 방법으로 일기 쓰기가 도움을 줄 수 있군요.","sourceDialogue":585,"category":"자아·성격","label":"General"},{"id":289,"text":"감정일기 작성을 통해 자신의 감정을 분석하고 원인을 고찰하며 어느 정도 도움을 받으셨군요.","sourceDialogue":539,"category":"자아·성격","label":"Complex Reflection"},{"id":290,"text":"감정적으로 많이 힘들어하시면서도, 그 상태를 어떻게 다루어야 할지 방법을 찾지 못하고 계시는 것 같네요.","sourceDialogue":101,"category":"정신건강","label":"Complex Reflection"},{"id":291,"text":"감정적으로 상당히 예민해지시고 자아 존중감에 심각한 타격을 받으신 것 같군요.","sourceDialogue":39,"category":"정신건강","label":"Complex Reflection"},{"id":292,"text":"경청하려는 노력은 이미 중요한 진전을 의미합니다.","sourceDialogue":214,"category":"대인관계","label":"Affirm"},{"id":293,"text":"고민 중인 상황 속에서도 앞으로 나아가려는 노력이 느껴집니다.","sourceDialogue":57,"category":"정신건강","label":"Affirm"},{"id":294,"text":"관계 속에서 겪는 불안감이 큰 부담으로 작용하고 있군요.","sourceDialogue":189,"category":"정신건강","label":"Complex Reflection"},{"id":295,"text":"관계가 지속될 지에 대한 걱정은 친구를 사귈 때 자연스러운 우려입니다.","sourceDialogue":201,"category":"대인관계","label":"General"},{"id":296,"text":"구체적인 방향을 찾으시려는 노력이 중요한 첫걸음이 될 수 있겠네요.","sourceDialogue":984,"category":"가족","label":"Affirm"},{"id":297,"text":"그 과거를 돌아보는 과정에서 자신을 더 깊이 이해하려는 노력이 느껴집니다.","sourceDialogue":765,"category":"취업·진로","label":"Affirm"},{"id":298,"text":"그 기분을 바꾸고자 하는 마음이 중요한 출발점이 될 수 있을 겁니다.","sourceDialogue":107,"category":"정신건강","label":"Affirm"},{"id":299,"text":"그 느낌에 대처하려는 노력조차 힘들 때도 있습니다.","sourceDialogue":169,"category":"정신건강","label":"General"},{"id":300,"text":"그 느낌은 잃고 싶지 않은 소중한 감정이었을 거예요.","sourceDialogue":11,"category":"정신건강","label":"Complex Reflection"},{"id":301,"text":"그 분야에 대해 탐색하고 싶으신 마음이 이미 준비의 첫걸음을 내딛은 것이네요.","sourceDialogue":41,"category":"정신건강","label":"Affirm"},{"id":302,"text":"그 실망감을 이겨내고자 하는 마음이 굉장히 진실하게 다가오네요.","sourceDialogue":51,"category":"정신건강","label":"Affirm"},{"id":303,"text":"그런 걱정들이 많을 때 마음이 무겁고 힘들 수 있어요.","sourceDialogue":105,"category":"정신건강","label":"Complex Reflection"},{"id":304,"text":"그런 고민 속에서도 변화를 위한 노력을 생각하고 계시는군요.","sourceDialogue":128,"category":"정신건강","label":"Affirm"},{"id":305,"text":"그런 상황에서도 솔직하게 마음을 표현해 주셔서 감사해요.","sourceDialogue":53,"category":"정신건강","label":"Affirm"},{"id":306,"text":"긍정적인 측면을 보고자 하는 바람은 매우 자연스러운 것입니다.","sourceDialogue":557,"category":"자아·성격","label":"General"},{"id":307,"text":"내면의 불안함을 관리하려는 의지를 가지고 계시는국요, 이는 매우 중요한 자각입니다.","sourceDialogue":521,"category":"자아·성격","label":"Affirm"},{"id":308,"text":"대화법과 감정 조절 기법을 배우고자 하는 의지가 분명히 성장으로 이끌 것입니다.","sourceDialogue":550,"category":"자아·성격","label":"Affirm"},{"id":309,"text":"더 나은 자신을 향해 노력하려는 결단력이 높아 보입니다.","sourceDialogue":428,"category":"자아·성격","label":"Affirm"},{"id":310,"text":"도전에 맞서 싸울 준비가 된 태도로 이야기해주셔서 용기있게 느껴집니다.","sourceDialogue":428,"category":"자아·성격","label":"Affirm"},{"id":311,"text":"두려움을 조금씩 떨쳐내고자 하는 의지를 가지고 계시다니, 정말 용기있는 결정입니다.","sourceDialogue":407,"category":"자아·성격","label":"Affirm"},{"id":312,"text":"마음속으로 스스로 해결하려는 시도는 쉽지 않은 도전이었을 거예요.","sourceDialogue":30,"category":"정신건강","label":"Complex Reflection"},{"id":313,"text":"마음을 열고 소통하는 방법에 대해 고민하시는 과정 역시 성장을 위한 중요한 경험이 되실 겁니다.","sourceDialogue":316,"category":"대인관계","label":"Affirm"},{"id":314,"text":"마음이 가벼워지는 활동을 찾아보고자 하는 의지가 있으시네요.","sourceDialogue":114,"category":"정신건강","label":"Affirm"},{"id":315,"text":"마음이 혼란스러워하는 것은 상황을 이해하고 해결하고자 하는 과정 중 하나일 수 있어요.","sourceDialogue":81,"category":"정신건강","label":"Complex Reflection"},{"id":316,"text":"말투와 태도에 대한 이해를 통해 관계를 개선하려는 노력을 고려하고 계시군요.","sourceDialogue":956,"category":"가족","label":"Complex Reflection"},{"id":317,"text":"모든 것을 내려놓고 싶은 마음까지 드는 상황이 굉장히 힘들어 보입니다.","sourceDialogue":146,"category":"정신건강","label":"Complex Reflection"},{"id":318,"text":"미래에 대한 생각으로 인해 불안감이 커지고 있는 상황을 이해합니다.","sourceDialogue":436,"category":"자아·성격","label":"Complex Reflection"},{"id":319,"text":"방향을 정하는 과정에 있어서 불확실성을 느끼는 것은 자연스러운 부분입니다.","sourceDialogue":480,"category":"자아·성격","label":"General"},{"id":320,"text":"변화를 위한 단계를 밟으려는 의지가 높아 보입니다. 성실한 노력이 돋보입니다.","sourceDialogue":162,"category":"정신건강","label":"Affirm"},{"id":321,"text":"변화를 위한 본인의 통찰과 노력을 중시하는 태도가 매우 중요하죠.","sourceDialogue":188,"category":"정신건강","label":"Affirm"},{"id":322,"text":"변화를 위한 접근을 시도하시는 용기가 대단하시네요.","sourceDialogue":284,"category":"대인관계","label":"Affirm"},{"id":323,"text":"변화를 향한 고민과 시도에 대해 고민하는 것 자체가 이미 큰 진전입니다.","sourceDialogue":128,"category":"정신건강","label":"Affirm"},{"id":324,"text":"변화를 향한 의지를 가지고 계시다니, 용기 있는 결정입니다.","sourceDialogue":292,"category":"대인관계","label":"Affirm"},{"id":325,"text":"변화에 대한 열린 마음이 중요한 첫 걸음임을 인지하고 계시군요.","sourceDialogue":557,"category":"자아·성격","label":"Affirm"},{"id":326,"text":"변화에 대한 용기를 내시려는 모습이 보기 좋습니다.","sourceDialogue":243,"category":"대인관계","label":"Affirm"},{"id":327,"text":"변화하고자 하는 마음을 가지신 것에 대해 감사드립니다.","sourceDialogue":348,"category":"대인관계","label":"Affirm"},{"id":328,"text":"부담감으로 인해 호흡조차 힘들어지는 상황에 계시군요.","sourceDialogue":113,"category":"정신건강","label":"Complex Reflection"},{"id":329,"text":"부담감을 줄이고자 하는 의지가 있으시다면, 그것만으로도 이미 중요한 시작을 하신 셈이네요.","sourceDialogue":277,"category":"대인관계","label":"Affirm"},{"id":330,"text":"부담스러운 책임감에 자유롭지 못한 마음을 느끼고 계시는군요.","sourceDialogue":976,"category":"가족","label":"Complex Reflection"},{"id":331,"text":"부정적인 감정들을 이해하고 대처하고자 하는 의지가 여러분을 더 건강한 정신 상태로 이끌 것입니다.","sourceDialogue":430,"category":"자아·성격","label":"Complex Reflection"},{"id":332,"text":"불안감 때문에 심장이 빨리 뛰는 것이 힘들어 보입니다.","sourceDialogue":537,"category":"자아·성격","label":"Complex Reflection"},{"id":333,"text":"불안을 줄이는 데 있어 자연스러운 방법을 시도해보고자 하는 접근은 중요한 발걸음이 될 수 있겠군요.","sourceDialogue":66,"category":"정신건강","label":"Complex Reflection"},{"id":334,"text":"불안을 해소하는 방법을 찾기 위해 노력하시는군요.","sourceDialogue":439,"category":"자아·성격","label":"Affirm"},{"id":335,"text":"사랑하는 사람의 긍정적인 변화를 바라는 것은 아름다운 일입니다.","sourceDialogue":953,"category":"가족","label":"Affirm"},{"id":336,"text":"사소한 일에 대한 예민한 반응과 울음이 본인 스스로도 부담이 되고 계시는군요.","sourceDialogue":5,"category":"정신건강","label":"Complex Reflection"},{"id":337,"text":"상황에 따라 느끼는 감정이 서로 다를 수 있어서 이해됩니다.","sourceDialogue":363,"category":"대인관계","label":"General"},{"id":338,"text":"상황으로 인해 원하는 변화를 실현하기 힘들어하고 계시네요.","sourceDialogue":952,"category":"가족","label":"Complex Reflection"},{"id":339,"text":"새로운 관점으로 자신을 바라보려는 의지가 대단하시네요.","sourceDialogue":974,"category":"가족","label":"Affirm"},{"id":340,"text":"새로운 대처 방법을 찾으려는 노력이 현재의 어려움을 극복하는 데 도움이 될 거예요.","sourceDialogue":455,"category":"자아·성격","label":"Affirm"},{"id":341,"text":"새로운 도전에 앞서 불확실함과 두려움을 느끼는 건 자연스러운 일이에요.","sourceDialogue":512,"category":"자아·성격","label":"General"},{"id":342,"text":"서로 이해하고 소통하는 관계를 향한 바람이 가족과의 더 긍정적인 관계를 만들어 갈 수 있는 동기가 되겠네요.","sourceDialogue":264,"category":"대인관계","label":"Complex Reflection"},{"id":343,"text":"서로의 시간을 존중하며 한 주에 한 번 근황을 공유하는 방식으로 건강한 관계를 유지하고자 하시는군요.","sourceDialogue":990,"category":"가족","label":"Complex Reflection"},{"id":344,"text":"성과와 긍정적인 측면을 기록하고자 하는 시도는 정말 소중한 단계입니다.","sourceDialogue":290,"category":"대인관계","label":"Affirm"},{"id":345,"text":"소통에 대한 고민이 많으신 시기라는 걸 이해합니다.","sourceDialogue":405,"category":"자아·성격","label":"General"},{"id":346,"text":"소통을 통해 관계를 개선하고자 하는 노력이 대단하시네요.","sourceDialogue":519,"category":"자아·성격","label":"Affirm"},{"id":347,"text":"소통이 원활하지 않아서 마음이 무척 힘들어하시는군요.","sourceDialogue":994,"category":"가족","label":"Complex Reflection"},{"id":348,"text":"솔직한 마음 표현은 관계 개선을 위한 좋은 출발점이 될 수 있겠네요.","sourceDialogue":972,"category":"가족","label":"General"},{"id":349,"text":"스스로 지치고 자존감이 떨어진다 느끼시는군요.","sourceDialogue":215,"category":"대인관계","label":"Complex Reflection"},{"id":350,"text":"스스로를 자책하게 되는 순간들이 있으시군요.","sourceDialogue":104,"category":"정신건강","label":"Complex Reflection"},{"id":351,"text":"스스로의 경험을 온전히 이해받지 못하고 상황을 가볍게 여겨지는 듯한 느낌을 받으셨군요.","sourceDialogue":157,"category":"정신건강","label":"Complex Reflection"},{"id":352,"text":"시간이 흐르며 스스로에 대한 이해가 깊어지신 것 같네요.","sourceDialogue":216,"category":"대인관계","label":"Complex Reflection"},{"id":353,"text":"시댁과의 관계와 개인적 공간에 대한 존중감 손실로 인해 마음이 상당히 무거워지셨군요.","sourceDialogue":227,"category":"대인관계","label":"Complex Reflection"},{"id":354,"text":"시작점을 찾기 어려울 때가 있음을 이해합니다.","sourceDialogue":976,"category":"가족","label":"General"},{"id":355,"text":"시작하기 전에 느끼는 막연함은 자연스러운 반응이에요.","sourceDialogue":11,"category":"정신건강","label":"General"},{"id":356,"text":"신체적, 정신적 건강을 중시하며 스스로 회복의 시간을 고려하고 계시는군요.","sourceDialogue":321,"category":"대인관계","label":"Complex Reflection"},{"id":357,"text":"실패 경험과 부정적인 말들이 자신감에 영향을 미치는 건 이해가 됩니다.","sourceDialogue":975,"category":"가족","label":"Complex Reflection"},{"id":358,"text":"실패에 대해 너무 자책하는 감정과 막막함 속에서도 실질적인 해결책을 모색하고 싶은 욕구가 있네요.","sourceDialogue":522,"category":"자아·성격","label":"Complex Reflection"},{"id":359,"text":"압박감 속에서도 자신에게 맞는 방법을 찾으려는 노력이 인상 깊습니다.","sourceDialogue":61,"category":"정신건강","label":"Affirm"},{"id":360,"text":"어려움을 마주하고도 새로운 환경에 도전하신 그 용기가 대단하네요.","sourceDialogue":126,"category":"정신건강","label":"Affirm"},{"id":361,"text":"어렸을 때부터 친구들을 믿지 못하는 경험과 예전의 상황이 지금의 죄책감과 불안함을 만들어내고 있네요.","sourceDialogue":331,"category":"대인관계","label":"Complex Reflection"},{"id":362,"text":"업무 외의 시간에도 마음의 여유를 찾지 못하고 계시는 거군요.","sourceDialogue":431,"category":"자아·성격","label":"Complex Reflection"},{"id":363,"text":"여러 해결책을 모색하는 과정 속에서 스스로에 대해 더 깊이 이해하게 되는국면에 있군요.","sourceDialogue":493,"category":"자아·성격","label":"Complex Reflection"},{"id":364,"text":"오랜 고민 끝에 자신의 길을 찾으려는 노력은 분명 가치 있는 일이에요.","sourceDialogue":669,"category":"취업·진로","label":"Affirm"},{"id":365,"text":"외로움과 새로운 사람들과의 관계 형성에 대한 불안이 주요 고민으로 느껴지시는군요.","sourceDialogue":246,"category":"대인관계","label":"Complex Reflection"},{"id":366,"text":"운동을 시작하기 위해 걷기를 선택하신 것, 건강한 삶으로 나아가려는 긍정적인 첫걸음임이 분명합니다.","sourceDialogue":567,"category":"자아·성격","label":"Affirm"},{"id":367,"text":"이런 고민을 해결하기 위해 도움을 청하신 것도 용기 있는 결정이었습니다.","sourceDialogue":899,"category":"학업·고시","label":"Affirm"},{"id":368,"text":"이해와 배려의 중요성을 깨달으셨다니, 관계를 바라보는 깊고 성숙한 시각을 갖게 되셨군요.","sourceDialogue":222,"category":"대인관계","label":"Complex Reflection"},{"id":369,"text":"인간관계에 대한 생각이 깊어질 때 우리는 자신의 주변 환경과 감정을 더 많이 고민하게 되죠.","sourceDialogue":388,"category":"대인관계","label":"General"},{"id":370,"text":"일기를 통해 감정을 다루는 경험이 이번에도 도움이 될 수 있겠군요.","sourceDialogue":987,"category":"가족","label":"Complex Reflection"},{"id":371,"text":"일상 대화에서 솔직함을 선택하려는 계획은 스스로에게 성실한 사람이 되기 위한 좋은 출발점이 될 것입니다.","sourceDialogue":468,"category":"자아·성격","label":"Complex Reflection"},{"id":372,"text":"일상 생활을 돌보는 데 필요한 에너지가 부족하시다고 느끼시는군요.","sourceDialogue":121,"category":"정신건강","label":"Complex Reflection"},{"id":373,"text":"일을 지속하는 것이 몸과 마음에 부담을 주고 있음에도 불구하고 경제적인 안정과 이직의 어려움에 대한 걱정 때문에 신중하게 접근하고 계시네요.","sourceDialogue":672,"category":"취업·진로","label":"Complex Reflection"},{"id":374,"text":"일자리 선택은 역시 중대한 결정이기에 그런 감정이 드는 건 자연스럽습니다.","sourceDialogue":674,"category":"취업·진로","label":"Complex Reflection"},{"id":375,"text":"자신감을 얻으셨다니, 대화를 통한 성찰의 중요성을 잘 이해하고 계시는군요.","sourceDialogue":216,"category":"대인관계","label":"Affirm"},{"id":376,"text":"자신감을 회복하고 싶은 마음이 굉장히 중요한 동기가 되고 있군요.","sourceDialogue":342,"category":"대인관계","label":"Complex Reflection"},{"id":377,"text":"자신에 대한 이해를 높이려는 노력에도 불구하고 해결책을 찾기 어려운 상황에 계시네요.","sourceDialogue":447,"category":"자아·성격","label":"Complex Reflection"},{"id":378,"text":"자신에 대해 긍정적으로 생각하려는 노력이 힘들어지고 있는 상황이시네요.","sourceDialogue":45,"category":"정신건강","label":"Complex Reflection"},{"id":379,"text":"자신에게 맞는 일을 찾기 위해 깊이 이해하려는 노력이 느껴집니다.","sourceDialogue":657,"category":"취업·진로","label":"Affirm"},{"id":380,"text":"자신을 긍정적으로 바라보려는 생각이 더 자신감 있고 여유로운 대인 관계로 이어질 수 있습니다.","sourceDialogue":228,"category":"대인관계","label":"Complex Reflection"},{"id":381,"text":"자신을 긍정적으로 바라볼 수 있는 방법을 찾으려는 노력이 멋집니다.","sourceDialogue":546,"category":"자아·성격","label":"Affirm"},{"id":382,"text":"자신을 다독이며 용기를 내려는 시도도 대단한 거예요.","sourceDialogue":335,"category":"대인관계","label":"Affirm"},{"id":383,"text":"자신을 더 잘 이해하고자 하며, 타인과의 관계에서 긍정적인 변화를 원하시는군요.","sourceDialogue":448,"category":"자아·성격","label":"Complex Reflection"},{"id":384,"text":"자신을 우선시하지 못하고 지속적으로 남을 돕는 일로 인해 지치고 공허함을 느끼시는 상황이신 것 같습니다.","sourceDialogue":449,"category":"자아·성격","label":"Complex Reflection"},{"id":385,"text":"자신을 위한 삶을 살고 싶다는 결심을 하신 건 정말 중요한 발걸음입니다.","sourceDialogue":960,"category":"가족","label":"Affirm"},{"id":386,"text":"자신을 위해 긍정적인 변화를 모색하시려는 정말 중요한 발걸음을 내디디셨네요.","sourceDialogue":508,"category":"자아·성격","label":"Affirm"},{"id":387,"text":"자신을 이해하려는 과정에서 발견하게 될 긍정적인 변화들을 기대해도 좋을 것 같네요.","sourceDialogue":428,"category":"자아·성격","label":"Complex Reflection"},{"id":388,"text":"자신을 이해하려는 노력이 여러분의 성장에 긍정적인 영향을 줄 것입니다.","sourceDialogue":446,"category":"자아·성격","label":"Complex Reflection"},{"id":389,"text":"자신을 존중받기 위한 노력을 시작하시려는군요.","sourceDialogue":352,"category":"대인관계","label":"General"},{"id":390,"text":"자신의 감정을 인식하고 그것이 어떻게 자신을 힘들게 하는지 아는 것은 중요한 인식입니다.","sourceDialogue":314,"category":"대인관계","label":"Complex Reflection"},{"id":391,"text":"자신의 감정을 표출하지 못하는 것이 부담스럽게 느껴지시는군요.","sourceDialogue":45,"category":"정신건강","label":"Complex Reflection"},{"id":392,"text":"자신의 관심사를 넓히고자 하는 과정에서 적극적으로 정보를 찾으려는 노력이 돋보입니다.","sourceDialogue":574,"category":"자아·성격","label":"Affirm"},{"id":393,"text":"자신의 능력을 믿으며 노력하는 과정에서 자신감이 서서히 회복되고 있는 것 같네요.","sourceDialogue":845,"category":"학업·고시","label":"Affirm"},{"id":394,"text":"자신의 삶에서 긍정적인 변화를 추구하고자 하는 강한 의지를 가지고 계시네요.","sourceDialogue":65,"category":"정신건강","label":"Affirm"},{"id":395,"text":"자신의 역할에 대해 고민을 깊이 하시는 걸 보니 내부적 성찰에 진지하신 것 같습니다.","sourceDialogue":182,"category":"정신건강","label":"Affirm"},{"id":396,"text":"자신의 의견을 표현하고자 하는 용기를 내시는 것, 대단히 용기 있는 결정이십니다.","sourceDialogue":223,"category":"대인관계","label":"Affirm"},{"id":397,"text":"자신의 필요를 인식하고 충족시키기 위한 방법을 알고 싶어하는 마음이 이루어질 때 큰 발전을 경험하시게 될 겁니다.","sourceDialogue":570,"category":"자아·성격","label":"Complex Reflection"},{"id":398,"text":"자신의 한계와 스트레스의 원인을 인지하고 그것을 개선하려는 노력이 대단히 존경스럽습니다.","sourceDialogue":462,"category":"자아·성격","label":"Affirm"},{"id":399,"text":"자신이 변화할 수 있다는 믿음을 갖는 것이 중요합니다.","sourceDialogue":557,"category":"자아·성격","label":"Affirm"},{"id":400,"text":"자연스럽게 대인 관계를 유지하려는 노력이 중요한 부분이 되고 있군요.","sourceDialogue":327,"category":"대인관계","label":"General"},{"id":401,"text":"작은 상황부터 연습해보기로 한 결정이 실제 상황에서도 도움이 될 것 같네요.","sourceDialogue":377,"category":"대인관계","label":"Affirm"},{"id":402,"text":"주변에서 비슷한 경험을 공유할 사람이 없어서, 혼자서만 겪고 있는 것 같은 외로움을 느끼고 계시는 군요.","sourceDialogue":164,"category":"정신건강","label":"Complex Reflection"},{"id":403,"text":"직업을 선택하는 과정에서 그 혼란이 더 커질 수 있음을 이해합니다.","sourceDialogue":507,"category":"자아·성격","label":"Complex Reflection"},{"id":404,"text":"진짜 감정을 이야기하는 용기와 그것이 중요함을 아는 깊이 있는 인식을 보여주셨군요.","sourceDialogue":216,"category":"대인관계","label":"Affirm"},{"id":405,"text":"집 안일과 산책이 마음을 달래주는데 도움이 되었군요.","sourceDialogue":123,"category":"정신건강","label":"General"},{"id":406,"text":"치유와 이해를 통한 발전을 원하시는 것은 매우 건강한 방향이네요.","sourceDialogue":209,"category":"대인관계","label":"Affirm"},{"id":407,"text":"친구에게 마음을 진솔하게 전하는 건 서로의 이해와 관계 강화에 중요한 역할을 할 수 있습니다.","sourceDialogue":237,"category":"대인관계","label":"Give Information"},{"id":408,"text":"타인의 감정을 이해하고 공감하는 능력은 관계 형성에 중요한 역할을 하며, 상호 이해를 바탕으로 한 커뮤니케이션은 관계를 강화시킬 수 있다고 합니다.","sourceDialogue":337,"category":"대인관계","label":"Give Information"},{"id":409,"text":"탐색하는 과정에서 어려운 순간도 있겠지만 변화를 위한 소중한 발걸음이겠죠.","sourceDialogue":987,"category":"가족","label":"Complex Reflection"},{"id":410,"text":"현재 상황에서 벗어나려는 의지를 가지고 계시네요. 용기 있는 결정입니다.","sourceDialogue":42,"category":"정신건강","label":"Affirm"},{"id":411,"text":"호흡을 통해 마음을 조절하고자 하는 의지가 엿보이네요.","sourceDialogue":38,"category":"정신건강","label":"Affirm"},{"id":412,"text":"혼자 있을 때 드는 외로움이 사랑받지 못할 것 같은 두려움으로 이어지는군요.","sourceDialogue":496,"category":"자아·성격","label":"Complex Reflection"},{"id":413,"text":"혼자가 될지도 모른다는 생각과 진정으로 이해받는 관계를 맺기에 대한 의문이 많이 괴롭히시는군요.","sourceDialogue":273,"category":"대인관계","label":"Complex Reflection"},{"id":414,"text":"혼자만의 시간을 원하며 개인적인 활동을 하고 싶어하는 마음이 강하게 드러나네요.","sourceDialogue":49,"category":"정신건강","label":"Complex Reflection"},{"id":415,"text":"화를 다스리려는 노력을 보이고 계시네요. 변화를 추구하는 본인의 의지가 대단합니다.","sourceDialogue":568,"category":"자아·성격","label":"Affirm"},{"id":416,"text":"회복 과정의 시작이 막막하게 느껴지시는 것 같습니다.","sourceDialogue":958,"category":"가족","label":"Complex Reflection"},{"id":417,"text":"후회와 고민 속에서도 자신의 감정을 직면하려는 용기가 있으시군요.","sourceDialogue":784,"category":"취업·진로","label":"Affirm"},{"id":418,"text":"힘들고 지쳐있을 때 자신을 돌보는 방법에 대해서도 생각하고 계시는군요.","sourceDialogue":630,"category":"취업·진로","label":"General"},{"id":419,"text":"가족 건강 문제는 정말 마음에 큰 짐을 줍니다.","sourceDialogue":992,"category":"가족","label":"General"},{"id":420,"text":"가족을 생각하는 마음이 변화를 위한 원동력이 되고 있네요.","sourceDialogue":262,"category":"대인관계","label":"Complex Reflection"},{"id":421,"text":"감정 관리에 있어 더 나은 접근 방법을 찾고 싶은 마음이 있으신 것 같네요.","sourceDialogue":597,"category":"자아·성격","label":"Complex Reflection"},{"id":422,"text":"감정 조절 방법을 배우고자 하는 의지를 가지고 계시군요.","sourceDialogue":417,"category":"자아·성격","label":"Affirm"},{"id":423,"text":"감정과 표현에 대한 부담으로 인해 예전의 자신감을 잃고 계시는군요.","sourceDialogue":362,"category":"대인관계","label":"Complex Reflection"},{"id":424,"text":"감정을 공유해주셔서 감사합니다. 에너지가 필요할 때 이곳에서 함께 해 드리겠습니다.","sourceDialogue":796,"category":"취업·진로","label":"Affirm"},{"id":425,"text":"감정을 다스리고 스스로를 보살피는 방법을 배우고자 하시는군요.","sourceDialogue":151,"category":"정신건강","label":"Complex Reflection"},{"id":426,"text":"감정을 드러내는 것에 대해 스스로를 다치게 할까 봐 우려하시는 것 같군요.","sourceDialogue":562,"category":"자아·성격","label":"Complex Reflection"},{"id":427,"text":"감정을 이해하고자 하는 여정은 자신을 돌아보고 성장하는 데 중요한 역할을 할 수 있습니다.","sourceDialogue":616,"category":"취업·진로","label":"General"},{"id":428,"text":"감정을 표현하는 것과 상대방에 대한 배려 사이에서 혼란을 겪고 계시네요.","sourceDialogue":233,"category":"대인관계","label":"Complex Reflection"},{"id":429,"text":"감정을 표현함으로써 나약해 보이거나 남에게 부담을 줄까 봐 걱정되시는군요.","sourceDialogue":552,"category":"자아·성격","label":"Complex Reflection"},{"id":430,"text":"감정의 무게를 혼자 짊어지고 계시는 상황이군요.","sourceDialogue":113,"category":"정신건강","label":"Complex Reflection"},{"id":431,"text":"감정의 변화가 행동에 긍정적인 변화를 가져오기도 합니다.","sourceDialogue":467,"category":"자아·성격","label":"General"},{"id":432,"text":"감정의 변화를 관찰하며 그것을 다루는 방법을 알고 싶어하는 것은 중요한 과정입니다.","sourceDialogue":110,"category":"정신건강","label":"General"},{"id":433,"text":"감정의 변화를 인식하고 계시는 건 중요한 과정이에요.","sourceDialogue":145,"category":"정신건강","label":"General"},{"id":434,"text":"감정의 악순환에 빠지셔서 힘들어하고 계시는군요.","sourceDialogue":1,"category":"정신건강","label":"Complex Reflection"},{"id":435,"text":"감정이 격해지면서 스스로의 상황에 대한 슬픔이 밀려오는군요.","sourceDialogue":103,"category":"정신건강","label":"Complex Reflection"},{"id":436,"text":"건강한 몸 상태를 회복하고 학습에 집중할 수 있는 방안에 대해 탐색하는 과정이 지금 필요한 시점이군요.","sourceDialogue":862,"category":"학업·고시","label":"Complex Reflection"},{"id":437,"text":"건강한 생활로 나아가려는 노력이 올바른 방향으로 나아가고 있음을 보여줍니다.","sourceDialogue":81,"category":"정신건강","label":"Affirm"},{"id":438,"text":"결정을 내릴 때 다른 사람의 의견에 영향을 많이 받는다는 건 선택의 과정이 쉽지 않음을 의미하네요.","sourceDialogue":421,"category":"자아·성격","label":"Complex Reflection"},{"id":439,"text":"경험을 통해 자기 이해의 깊이를 더하는 과정에서 중요한 인사이트를 얻고 계시네요.","sourceDialogue":6,"category":"정신건강","label":"General"},{"id":440,"text":"경험한 일들이 회복 과정에 있어 중요한 요인으로 작용하고 계시군요.","sourceDialogue":982,"category":"가족","label":"Complex Reflection"},{"id":441,"text":"공감적 경청과 약속을 지키고자 하는 노력은 좋은 관계를 만드는데 중요한 열쇠입니다.","sourceDialogue":258,"category":"대인관계","label":"Affirm"},{"id":442,"text":"과거를 받아들이려는 노력은 큰 발전의 신호로 보입니다.","sourceDialogue":97,"category":"정신건강","label":"Affirm"},{"id":443,"text":"관계에서의 일관성을 추구하시려는 노력이 대단히 인상 깊습니다.","sourceDialogue":323,"category":"대인관계","label":"Affirm"},{"id":444,"text":"관계와 감정을 다루는 방법에 대해 고민해오셨네요.","sourceDialogue":347,"category":"대인관계","label":"General"},{"id":445,"text":"귀하의 마음을 열고 공유해 주셔서 감사합니다.","sourceDialogue":252,"category":"대인관계","label":"Affirm"},{"id":446,"text":"그 기대에 맞추기 위해 스스로에게 너무 큰 부담을 지우고 계시는군요.","sourceDialogue":329,"category":"대인관계","label":"Complex Reflection"},{"id":447,"text":"그 기쁨이 인정의 가치를 실감하게 하는군요.","sourceDialogue":467,"category":"자아·성격","label":"Affirm"},{"id":448,"text":"그 노력을 통해 발전하는 모습이 기대됩니다.","sourceDialogue":467,"category":"자아·성격","label":"Affirm"},{"id":449,"text":"그 동안 가족과의 관계로 인해 상처를 받으신 것 같네요.","sourceDialogue":954,"category":"가족","label":"Complex Reflection"},{"id":450,"text":"그 불안함이 상대방에게 전달되어 부담을 주시는 걸 염려하고 계시군요.","sourceDialogue":543,"category":"자아·성격","label":"Complex Reflection"},{"id":451,"text":"그러셨군요, 가끔은 어디서부터 시작해야 할지 모르는 것 자체가 큰 부담이 될 수 있습니다.","sourceDialogue":464,"category":"자아·성격","label":"General"},{"id":452,"text":"그러시군요. 불안할 때 스스로를 어루만지는 방법을 찾는 과정도 경험 중이신 것 같습니다.","sourceDialogue":178,"category":"정신건강","label":"Complex Reflection"},{"id":453,"text":"그런 감정들을 겪으면서 스스로를 많이 돌아보게 되셨군요.","sourceDialogue":6,"category":"정신건강","label":"Complex Reflection"},{"id":454,"text":"그런 감정을 느끼실 때 마음이 많이 어려우실 거예요.","sourceDialogue":152,"category":"정신건강","label":"Complex Reflection"},{"id":455,"text":"그런 두려움과 걱정은 인생의 큰 전환점에서 자연스럽게 느끼는 감정이죠.","sourceDialogue":786,"category":"취업·진로","label":"General"},{"id":456,"text":"그런 목표와 변화를 위해 고민하고 계시는 것 자체가 이미 큰 성장입니다.","sourceDialogue":217,"category":"대인관계","label":"Affirm"},{"id":457,"text":"그런 상황들이 정서적으로 상당한 부담을 주고 있을 거라 생각됩니다.","sourceDialogue":980,"category":"가족","label":"Complex Reflection"},{"id":458,"text":"그런 상황에서 자신의 감정을 드러내는 건 쉽지 않으셨겠어요.","sourceDialogue":981,"category":"가족","label":"Complex Reflection"},{"id":459,"text":"그런 생각이 든다니 상당히 힘들고 외로운 경험이 될 수 있겠군요.","sourceDialogue":296,"category":"대인관계","label":"Complex Reflection"},{"id":460,"text":"그림 그리기와 음악 듣기를 통해 마음의 안정을 찾으려는 노력이 중요하게 느껴지네요.","sourceDialogue":978,"category":"가족","label":"Complex Reflection"},{"id":461,"text":"그림을 다시 그리고 싶은 마음이 있지만, 준비물을 갖추고 개인적인 공간을 마련하는 것이 부담으로 다가오는군요.","sourceDialogue":116,"category":"정신건강","label":"Complex Reflection"},{"id":462,"text":"글쓰기 과제에 불안함을 느끼시는 건 완벽하게 해내고 싶은 마음이 있으신 것 같네요.","sourceDialogue":429,"category":"자아·성격","label":"Complex Reflection"},{"id":463,"text":"긍정적인 생각을 통해 자신감을 되찾으려는 노력이 보여집니다.","sourceDialogue":272,"category":"대인관계","label":"Affirm"},{"id":464,"text":"기록으로 인한 처음의 부담감도 시간이 지나면서 익숙해질 거에요.","sourceDialogue":473,"category":"자아·성격","label":"General"},{"id":465,"text":"긴장을 풀기 위한 노력이 상황을 조금이나마 개선시키는 데 도움이 되었으면 좋겠네요.","sourceDialogue":365,"category":"대인관계","label":"General"},{"id":466,"text":"나 자신에 대한 현재의 패턴을 인지하고 변화하고자 하는 의지를 가지고 계시군요. 이것이 상당히 존경스러운 태도입니다.","sourceDialogue":175,"category":"정신건강","label":"Affirm"},{"id":467,"text":"나아지고자 하는 의지를 가지고 계시네요. 겪고 계시는 어려움에도 불구하고, 해결을 위한 방법을 찾으려는 노력이 대단합니다.","sourceDialogue":423,"category":"자아·성격","label":"Affirm"},{"id":468,"text":"내면에서 충돌이 일어나고 스트레스로 인해 감정적으로 힘들어하시는군요.","sourceDialogue":45,"category":"정신건강","label":"Complex Reflection"},{"id":469,"text":"노력에도 불구하고 원하는 대로 스스로를 돌보기가 어려웠군요.","sourceDialogue":680,"category":"취업·진로","label":"Complex Reflection"},{"id":470,"text":"노력하는 과정 자체가 긍정적인 변화로 이어지는 중요한 부분임을 인지하시고 계시네요.","sourceDialogue":348,"category":"대인관계","label":"Affirm"},{"id":471,"text":"노력해보겠다는 말씀은 이미 변화를 위한 중요한 단계를 밟고 계신 것이네요.","sourceDialogue":292,"category":"대인관계","label":"Affirm"},{"id":472,"text":"다른 사람들의 말로부터 자신을 보호하려는 의지가 느껴집니다.","sourceDialogue":151,"category":"정신건강","label":"Affirm"},{"id":473,"text":"다양한 취미 활동을 통해 자신의 관심사를 발견하려는 시도가 도움이 될 것임을 인지하셨네요.","sourceDialogue":563,"category":"자아·성격","label":"Complex Reflection"},{"id":474,"text":"대인 관계에서 오는 부담이 고립감을 증가시키고 있네요.","sourceDialogue":109,"category":"정신건강","label":"Complex Reflection"},{"id":475,"text":"대화가 어색해지면 긴장과 부담감을 느끼시며 자신도 당황하고 불편해지신다니, 힘든 경험이실 것 같습니다.","sourceDialogue":542,"category":"자아·성격","label":"Complex Reflection"},{"id":476,"text":"더 평온한 상태를 추구하시려는 노력이 대단하시네요.","sourceDialogue":588,"category":"자아·성격","label":"Affirm"},{"id":477,"text":"도전을 포기하지 않으려는 마음이 드신 건 정말 대단한 용기라고 생각합니다.","sourceDialogue":601,"category":"취업·진로","label":"Affirm"},{"id":478,"text":"도전을 피하는 것도 때로는 스스로를 보호하는 방법일 수 있습니다.","sourceDialogue":68,"category":"정신건강","label":"General"},{"id":479,"text":"동료들과의 대화를 통해 관계를 형성해 나가려는 노력이 대단합니다.","sourceDialogue":359,"category":"대인관계","label":"Affirm"},{"id":480,"text":"디지털 아트와 프로그래밍에 대한 관심이 새로운 가능성을 탐색하는 데 도움이 될 것입니다.","sourceDialogue":42,"category":"정신건강","label":"General"},{"id":481,"text":"마음이 가벼워진다는 것은 내적으로 어떤 변화가 시작되고 있음을 의미합니다.","sourceDialogue":217,"category":"대인관계","label":"Complex Reflection"},{"id":482,"text":"마음이 많이 무거우시겠군요. 숨 쉬기조차 힘든 정도로 부담이 크시다니 정말 어려운 상황이십니다.","sourceDialogue":56,"category":"정신건강","label":"Complex Reflection"},{"id":483,"text":"명확한 의사표현과 듣기 기술에 중점을 두려는 결정은 여러 상호작용에서 큰 도움이 될 것입니다.","sourceDialogue":441,"category":"자아·성격","label":"General"},{"id":484,"text":"몸과 마음이 끊임없이 피로를 겪고 계시군요.","sourceDialogue":149,"category":"정신건강","label":"Complex Reflection"},{"id":485,"text":"몸이 반응할 때마다 견디기만 하려고 노력하신다는 걸 알겠어요.","sourceDialogue":10,"category":"정신건강","label":"Complex Reflection"},{"id":486,"text":"방향을 잡는 것이 어려운 것은 이 과정에서 자연스러운 일입니다.","sourceDialogue":258,"category":"대인관계","label":"General"},{"id":487,"text":"변화를 시작해보고 싶다는 의지가 분명해 보이시네요.","sourceDialogue":86,"category":"정신건강","label":"Affirm"},{"id":488,"text":"변화를 위한 노력을 시작하고자 하는 마음이 중요합니다.","sourceDialogue":481,"category":"자아·성격","label":"Complex Reflection"},{"id":489,"text":"변화를 위한 방법을 찾는 과정에서 스스로를 탐색하고 계시군요.","sourceDialogue":180,"category":"정신건강","label":"General"},{"id":490,"text":"변화를 위해 생활 전반을 개선하고자 하는 의지가 높으시네요.","sourceDialogue":65,"category":"정신건강","label":"Affirm"},{"id":491,"text":"변화를 위해 적극적으로 방법을 찾으시려는 자세가 정말로 대단하시네요.","sourceDialogue":472,"category":"자아·성격","label":"Affirm"},{"id":492,"text":"변화를 위해 희망을 가지고 계시다니 용기 있는 자세를 보여주시는군요.","sourceDialogue":326,"category":"대인관계","label":"Affirm"},{"id":493,"text":"변화를 주고자 하는 의지를 가지고 계시네요.","sourceDialogue":171,"category":"정신건강","label":"Affirm"},{"id":494,"text":"변화에 대한 강한 의지는 어려움에 맞서는 힘이 되겠네요.","sourceDialogue":558,"category":"자아·성격","label":"Affirm"},{"id":495,"text":"변화에 대한 희망을 갖게 되셨다니 고무적이네요.","sourceDialogue":408,"category":"자아·성격","label":"Affirm"},{"id":496,"text":"본인의 마음을 따르고자 하는 용기가 있으시네요.","sourceDialogue":792,"category":"취업·진로","label":"Affirm"},{"id":497,"text":"부담감이 증가하고 계시다는 것, 점점 더 무거워지는 마음을 느끼고 계시는군요.","sourceDialogue":585,"category":"자아·성격","label":"Complex Reflection"},{"id":498,"text":"불안과 슬픔이 마음 깊은 곳에서부터 밀려오고 있는 것 같네요.","sourceDialogue":153,"category":"정신건강","label":"Complex Reflection"},{"id":499,"text":"불안하게 만드는 상황에 적극적으로 대처하고자 하는 의지가 중요한 발판이 되겠군요.","sourceDialogue":100,"category":"정신건강","label":"Affirm"},{"id":500,"text":"비교는 종종 우리가 스스로를 엄격하게 판단하게 만들죠.","sourceDialogue":572,"category":"자아·성격","label":"General"},{"id":501,"text":"사람들과 더 따뜻한 관계를 형성하기 위해 자신을 열고자 하는 의지가 있군요.","sourceDialogue":447,"category":"자아·성격","label":"Affirm"},{"id":502,"text":"사람들의 반응 때문에 대화에 대한 열정이 더욱 소중하게 느껴지시나 봅니다.","sourceDialogue":566,"category":"자아·성격","label":"General"},{"id":503,"text":"상대방의 감정과 입장을 깊이 이해하려는 노력을 통해 효과적인 소통을 이루고자 하시는군요.","sourceDialogue":206,"category":"대인관계","label":"Complex Reflection"},{"id":504,"text":"상대방이 이해할 수 있도록 자신의 감정과 생각을 전달하는 방법을 알고 싶으신 거군요.","sourceDialogue":312,"category":"대인관계","label":"Complex Reflection"},{"id":505,"text":"상실의 경험 속에서도 삶에 긍정적인 변화를 주고자 하는 의지가 대단하시네요.","sourceDialogue":166,"category":"정신건강","label":"Affirm"},{"id":506,"text":"상황 관리에 있어서 균형을 찾으려는 노력이 보여집니다.","sourceDialogue":550,"category":"자아·성격","label":"Affirm"},{"id":507,"text":"상황에 대응하면서 강인함과 자신감을 기르고자 하는 의지가 느껴집니다.","sourceDialogue":456,"category":"자아·성격","label":"Affirm"},{"id":508,"text":"상황을 개선하고자 하는 용기를 내시는군요. 정말 용감하십니다.","sourceDialogue":112,"category":"정신건강","label":"Affirm"},{"id":509,"text":"상황을 이해하고 대처 방법을 배우고자 하는 욕구가 관건인 것으로 드러나네요.","sourceDialogue":10,"category":"정신건강","label":"General"},{"id":510,"text":"상황을 이해하려는 노력 자체가 위안이 되고 있네요.","sourceDialogue":412,"category":"자아·성격","label":"Complex Reflection"},{"id":511,"text":"상황을 통과하는 데 필요한 자신감을 쌓아가려는 노력이 인상 깊습니다.","sourceDialogue":698,"category":"취업·진로","label":"Affirm"},{"id":512,"text":"상황이 조금이라도 나아지기를 원하는 마음에서 시작된 변화의 과정이 보이네요.","sourceDialogue":967,"category":"가족","label":"Complex Reflection"},{"id":513,"text":"새로운 인연을 만들고자 하는 용기가 대단하시네요.","sourceDialogue":240,"category":"대인관계","label":"Affirm"},{"id":514,"text":"새로운 환경과 이전의 친구 관계에서의 변화로 인해 앞으로 나아갈 길에 대해 스스로 확신이 서지 않으시는 것 같네요.","sourceDialogue":240,"category":"대인관계","label":"Complex Reflection"},{"id":515,"text":"생각을 멈추려고 애쓰는 과정에서 겪는 어려움을 잘 이해합니다.","sourceDialogue":440,"category":"자아·성격","label":"General"},{"id":516,"text":"생활 속에서 숨쉬기조차 힘들 정도로 부담스러운 감정을 겪고 계시는군요.","sourceDialogue":624,"category":"취업·진로","label":"Complex Reflection"},{"id":517,"text":"서로를 이해하려는 노력이 문제 해결에 큰 역할을 할 수 있습니다.","sourceDialogue":991,"category":"가족","label":"General"},{"id":518,"text":"서로의 공간을 존중하면서 조심스러운 태도를 유지하고 계시군요.","sourceDialogue":32,"category":"정신건강","label":"General"},{"id":519,"text":"서로의 시간을 공유하며 엄마를 더 깊이 이해하고 서로에게 큰 힘이 되길 바라시는 것 같습니다.","sourceDialogue":986,"category":"가족","label":"Complex Reflection"},{"id":520,"text":"소통을 원하는 마음이 대화의 질을 높일 수 있는 좋은 출발점이 되겠네요.","sourceDialogue":991,"category":"가족","label":"General"},{"id":521,"text":"속에서 불안함이 커지는 건 자연스러운 반응입니다.","sourceDialogue":682,"category":"취업·진로","label":"General"},{"id":522,"text":"솔직한 감정 전달과 상대방의 이해를 구하려는 노력을 준비하고 계시군요.","sourceDialogue":301,"category":"대인관계","label":"Complex Reflection"},{"id":523,"text":"솔직한 대화로 자신을 이해받고자 하는 욕구가 생기셨네요.","sourceDialogue":560,"category":"자아·성격","label":"Complex Reflection"},{"id":524,"text":"스스로를 긍정적으로 바라보려는 연습은 힘든 과정일 수도 있지만, 매우 의미 있는 과정이 될 거에요.","sourceDialogue":375,"category":"대인관계","label":"Complex Reflection"},{"id":525,"text":"스스로를 받아들이는 것이 중요한 발견이었군요.","sourceDialogue":324,"category":"대인관계","label":"Affirm"},{"id":526,"text":"스스로에 대한 깊은 탐색 속에서도 답을 찾지 못했을 때 느껴지는 답답함은 당연한 것입니다.","sourceDialogue":471,"category":"자아·성격","label":"General"},{"id":527,"text":"스스로에 대한 불신감과 자기비하가 마음을 어렵게 만드는군요.","sourceDialogue":14,"category":"정신건강","label":"Complex Reflection"},{"id":528,"text":"스스로에게 조금 더 너그러워지고 싶으신 욕구가 강하신 것 같네요.","sourceDialogue":137,"category":"정신건강","label":"General"},{"id":529,"text":"스스로에게 친절해질 방법을 찾아보는 시도가 시작되었네요.","sourceDialogue":508,"category":"자아·성격","label":"General"},{"id":530,"text":"스트레스를 받는 상황에서도 건강을 유지하기 위해 노력하시는 모습이 보입니다.","sourceDialogue":133,"category":"정신건강","label":"Affirm"},{"id":531,"text":"시도해 보신다니, 어떤 변화가 일어날지 함께 지켜보는 것도 의미있을 것 같습니다.","sourceDialogue":16,"category":"정신건강","label":"General"},{"id":532,"text":"시작을 하기가 어렵고, 휴식조차 제대로 취하지 못하는 상태가 되셨군요.","sourceDialogue":114,"category":"정신건강","label":"Complex Reflection"},{"id":533,"text":"실제로 받는 관심과 위로가 마음의 치유에 도움이 될 것이라는 희망을 가지고 계시는군요.","sourceDialogue":416,"category":"자아·성격","label":"Complex Reflection"},{"id":534,"text":"실패에 대한 걱정은 어떠한 도전을 시작하기 전에 자연스러운 감정이에요.","sourceDialogue":631,"category":"취업·진로","label":"General"},{"id":535,"text":"실패하거나 잘못할 가능성에 대한 불안함이 상당한 부담을 안겨주고 있군요.","sourceDialogue":422,"category":"자아·성격","label":"Complex Reflection"},{"id":536,"text":"실행을 위한 준비 과정에 대해 적극적으로 고민하시는 점, 진심으로 대단하십니다.","sourceDialogue":78,"category":"정신건강","label":"Affirm"},{"id":537,"text":"앱을 삭제한 것이 마음의 부담을 완전히 해소시키지는 못했네요.","sourceDialogue":380,"category":"대인관계","label":"Complex Reflection"},{"id":538,"text":"어떤 활동에서 즐거움을 느끼는지 찾는 과정은 스스로에 대한 이해를 넓히고 깊게 하는 좋은 기회가 될 것입니다.","sourceDialogue":746,"category":"취업·진로","label":"General"},{"id":539,"text":"어려움 속에서도 자신만의 방식으로 시작하려는 의지를 보여주셨네요.","sourceDialogue":116,"category":"정신건강","label":"Affirm"},{"id":540,"text":"어려움 속에서도 평온함을 얻기 위한 노력을 하시려는 의지를 보여주셔서 높이 평가드립니다.","sourceDialogue":521,"category":"자아·성격","label":"Affirm"},{"id":541,"text":"어려움에도 불구하고 관계를 재건하고자 하는 노력이 대단하십니다.","sourceDialogue":376,"category":"대인관계","label":"Affirm"},{"id":542,"text":"업무를 통한 성과와 개인적인 만족 사이에서 균형을 찾으려는 노력이 보여집니다.","sourceDialogue":451,"category":"자아·성격","label":"Affirm"},{"id":543,"text":"역할에 대한 의미를 찾고자 하는 고민이 깊은 과정을 거치고 계시네요.","sourceDialogue":182,"category":"정신건강","label":"General"},{"id":544,"text":"오빠를 기억하며 슬픔을 조금씩 마주하려는 노력이 느껴집니다.","sourceDialogue":166,"category":"정신건강","label":"Affirm"},{"id":545,"text":"오빠를 도울 방법을 찾지 못해 느끼는 무력함이 힘들게 하고 있네요.","sourceDialogue":968,"category":"가족","label":"Complex Reflection"},{"id":546,"text":"외로움과 무기력함이 커다란 부담으로 느껴지시는군요.","sourceDialogue":235,"category":"대인관계","label":"Complex Reflection"},{"id":547,"text":"외로움을 느낀다는 것은 종종 내면의 감정과 대화하고 싶은 욕구가 있다는 신호일 수 있습니다.","sourceDialogue":261,"category":"대인관계","label":"Complex Reflection"},{"id":548,"text":"외롭고 자신을 의심하게 되는 감정은 타인과의 관계에서 빈번히 겪을 수 있는 일입니다.","sourceDialogue":287,"category":"대인관계","label":"General"},{"id":549,"text":"용기를 내어 솔직한 이야기를 나누려는 시도는 분명 큰 진전이 될 것입니다.","sourceDialogue":383,"category":"대인관계","label":"Affirm"},{"id":550,"text":"용기를 내어 시작하려는 마음을 가지셨다니 기쁩니다.","sourceDialogue":796,"category":"취업·진로","label":"Affirm"},{"id":551,"text":"운동을 통해 스트레스를 다루려는 시도는 소중한 경험이었을 거예요.","sourceDialogue":36,"category":"정신건강","label":"General"},{"id":552,"text":"이 시기에 겪는 어려움을 이겨내기 위해 많은 고민을 하고 계시네요.","sourceDialogue":54,"category":"정신건강","label":"Affirm"},{"id":553,"text":"이런 경험을 통해 자신에 대해 더 깊이 이해하게 되셨을 거예요.","sourceDialogue":355,"category":"대인관계","label":"General"},{"id":554,"text":"이런 고민으로부터 시작해서 스스로 해결 방향을 모색하게 되셨군요.","sourceDialogue":554,"category":"자아·성격","label":"General"},{"id":555,"text":"이런 고민을 나누며 해결의 실마리를 찾아가고자 하는 노력은 중요한 과정이에요.","sourceDialogue":993,"category":"가족","label":"General"},{"id":556,"text":"이런 복잡한 감정 속에서도 새로운 경험을 향한 열망을 유지하고 계시는 군요.","sourceDialogue":561,"category":"자아·성격","label":"Affirm"},{"id":557,"text":"이제 그 쌓인 부담감을 덜고 싶으신 마음이 크신 것 같군요.","sourceDialogue":423,"category":"자아·성격","label":"Complex Reflection"},{"id":558,"text":"이해되는 감정을 소통하며 웃을 수 있는 순간을 갈망하고 계시네요.","sourceDialogue":302,"category":"대인관계","label":"Complex Reflection"},{"id":559,"text":"일기를 통해 자신의 감정을 정리하고자 하시는 것은 건강한 자기 반성과 성장을 위한 좋은 접근 방식입니다.","sourceDialogue":159,"category":"정신건강","label":"General"},{"id":560,"text":"일상에서 놀라움이나 기대를 느끼지 못하는 현재 상황이 마음에 부담이 되고 있을 것 같네요.","sourceDialogue":202,"category":"대인관계","label":"Complex Reflection"},{"id":561,"text":"자기 이해에 대한 노력을 통해 자신과 더 깊이 연결하려는 시도를 하고 계시는군요.","sourceDialogue":202,"category":"대인관계","label":"General"},{"id":562,"text":"자신감 있는 태도를 향해 나아가고자 하는 열망이 느껴집니다.","sourceDialogue":572,"category":"자아·성격","label":"Affirm"},{"id":563,"text":"자신감을 얻기 위해 실천을 고려하시는 건 매우 의미 있는 발걸음이 될 것입니다.","sourceDialogue":548,"category":"자아·성격","label":"General"},{"id":564,"text":"자신에 대해 긍정적으로 생각하는 연습을 통해 자존감을 높이려는 노력을 하고 계시군요.","sourceDialogue":458,"category":"자아·성격","label":"Affirm"},{"id":565,"text":"자신에게 다정한 언어를 사용하는 연습은 자신감을 키우는 데에도 도움이 될 것 같네요.","sourceDialogue":137,"category":"정신건강","label":"Complex Reflection"},{"id":566,"text":"자신에게 필요한 변화를 인지하고 이를 실천할 방법을 찾으신 것, 대단히 현명한 접근입니다.","sourceDialogue":683,"category":"취업·진로","label":"Affirm"},{"id":567,"text":"자신을 더 깊이 탐색하려는 의지가 강하신 것을 알 수 있습니다.","sourceDialogue":563,"category":"자아·성격","label":"Affirm"},{"id":568,"text":"자신을 더 이해하고자 하는 용기와 결정을 내리셨군요.","sourceDialogue":829,"category":"학업·고시","label":"Affirm"},{"id":569,"text":"자신을 위한 작은 활동을 찾아보려는 시도는 정말 좋은 접근이시네요.","sourceDialogue":45,"category":"정신건강","label":"Affirm"},{"id":570,"text":"자신을 이해하고 받아들이는 과정은 정말 중요한 과정이라고 생각됩니다.","sourceDialogue":387,"category":"대인관계","label":"General"},{"id":571,"text":"자신을 이해하는 여정은 어려움 속에서도 성장하는 데 중요한 역할을 합니다.","sourceDialogue":320,"category":"대인관계","label":"General"},{"id":572,"text":"자신을 이해하려는 시도는 매우 중요하다고 할 수 있겠군요.","sourceDialogue":974,"category":"가족","label":"Complex Reflection"},{"id":573,"text":"자신을 찾아가고자 하는 방향성을 설정하신 것이 인상 깊습니다.","sourceDialogue":179,"category":"정신건강","label":"Affirm"},{"id":574,"text":"자신의 가치에 대해 의문을 가지실 때 마음이 많이 힘드시겠군요.","sourceDialogue":457,"category":"자아·성격","label":"Complex Reflection"},{"id":575,"text":"자신의 감정을 인식하려고 노력하시는 모습, 진심으로 대단하시네요.","sourceDialogue":632,"category":"취업·진로","label":"Affirm"},{"id":576,"text":"자신의 능력에 대한 의문과 타인의 시선에 대한 걱정으로 일과 여가 시간 모두에서 힘들어하고 계시네요.","sourceDialogue":524,"category":"자아·성격","label":"Complex Reflection"},{"id":577,"text":"자신의 상황을 긍정적으로 바라보고자 하는 의지를 가지고 계시다니, 그 자체로 이미 중요한 발전입니다.","sourceDialogue":168,"category":"정신건강","label":"Affirm"},{"id":578,"text":"자신의 생각을 보다 열린 마음으로 바꾸고자 하는 의지가 있으시군요.","sourceDialogue":395,"category":"대인관계","label":"Affirm"},{"id":579,"text":"자신의 욕구를 명확히 하면서도 상대방을 배려하는 방식을 찾고자 한다는 점에서 그 균형을 이루려는 노력이 엿보입니다.","sourceDialogue":307,"category":"대인관계","label":"Complex Reflection"},{"id":580,"text":"자신의 의지를 실행에 옮기려는 과정에서 얻은 경험은 가치가 있다고 할 수 있습니다.","sourceDialogue":421,"category":"자아·성격","label":"General"},{"id":581,"text":"자신이 좋아하는 것에 대해 고민하고 선택을 모색하는 과정에 있으시군요, 정말 중요한 발견을 하셨습니다.","sourceDialogue":727,"category":"취업·진로","label":"Affirm"},{"id":582,"text":"작은 성공들을 인정하고 기록하는 방법을 통해 긍정적인 변화를 모색하려는 시도가 도움이 될 것입니다.","sourceDialogue":175,"category":"정신건강","label":"Complex Reflection"},{"id":583,"text":"적절한 방식으로 화를 내는 것이 자신감을 높이고 다른 사람들로부터 존중받는 데 있어 중요하게 생각하시는군요.","sourceDialogue":592,"category":"자아·성격","label":"Complex Reflection"},{"id":584,"text":"적절한 휴식과 작업 시간을 조절하는 것이 균형을 찾는 데 도움이 될 것 같군요.","sourceDialogue":642,"category":"취업·진로","label":"Complex Reflection"},{"id":585,"text":"전문가에게 도움을 구하고자 하는 생각이 이미 변화에 대한 첫 걸음을 내딛는 것입니다.","sourceDialogue":92,"category":"정신건강","label":"Complex Reflection"},{"id":586,"text":"전문가의 도움을 찾으시는 과정에서 좀 더 다양한 관점과 해결 방안을 모색하고 싶으신 것 같네요.","sourceDialogue":177,"category":"정신건강","label":"General"},{"id":587,"text":"전문가의 조언을 구하려는 결정은 이해하려는 노력의 일환으로 보여집니다.","sourceDialogue":81,"category":"정신건강","label":"Complex Reflection"},{"id":588,"text":"주변 사람에게 긍정적인 영향을 주고 싶어하는 마음이 크신 거 같네요.","sourceDialogue":385,"category":"대인관계","label":"Affirm"},{"id":589,"text":"즐거움과 활기를 느끼는 경험을 추구하는 것은 매우 자연스러운 일입니다.","sourceDialogue":388,"category":"대인관계","label":"General"},{"id":590,"text":"진정한 이해를 주고받는 관계를 찾는 과정은 종종 어려움을 수반하곤 합니다.","sourceDialogue":157,"category":"정신건강","label":"Complex Reflection"},{"id":591,"text":"집에서 시간을 보내면서 느껴지는 안정감이 조금이라도 마음을 진정시키는 데 도움이 될 수도 있겠네요.","sourceDialogue":333,"category":"대인관계","label":"Complex Reflection"},{"id":592,"text":"창의성과 노력은 본인의 작품을 평가하는 데 매우 의미 있는 기준이 되고 있습니다.","sourceDialogue":452,"category":"자아·성격","label":"General"},{"id":593,"text":"추억을 함께 돌아보며 공유하는 시간이 서로에게 의미 있는 순간이 될 것 같네요.","sourceDialogue":957,"category":"가족","label":"General"},{"id":594,"text":"취미를 통해 자신을 이해하려는 과정에서 긍정적인 변화를 기대하고 계시는군요.","sourceDialogue":563,"category":"자아·성격","label":"Complex Reflection"},{"id":595,"text":"친구들과의 대화가 잠시나마 마음의 무게를 덜어주며, 그 소중한 순간들이 위안을 주고 있다는 걸 중요하게 여기시는군요.","sourceDialogue":171,"category":"정신건강","label":"Complex Reflection"},{"id":596,"text":"패턴을 이해하려는 노력이 변화로 이어질 가능성을 열어놓고 계시군요.","sourceDialogue":86,"category":"정신건강","label":"Complex Reflection"},{"id":597,"text":"현재의 상태에서 변화하고자 하는 의지가 강하게 느껴집니다.","sourceDialogue":580,"category":"자아·성격","label":"Affirm"},{"id":598,"text":"혼자 계실 때 마음이 무겁게 느껴지시는군요.","sourceDialogue":172,"category":"정신건강","label":"Complex Reflection"},{"id":599,"text":"혼자 생각하는 시간도 중요하지만, 때로는 그것이 충분하지 않을 수도 있죠.","sourceDialogue":60,"category":"정신건강","label":"General"},{"id":600,"text":"혼자 있을 때는 불안과 우울함이 다시 찾아오시는 것 같군요.","sourceDialogue":58,"category":"정신건강","label":"Complex Reflection"},{"id":601,"text":"가정 내에서 불화와 부정적인 태도로 인해 불안정함과 우울함을 느끼고 계시네요.","sourceDialogue":980,"category":"가족","label":"Complex Reflection"},{"id":602,"text":"가족 간의 관계에서 상당한 갈등과 스트레스를 느끼고 계시는군요.","sourceDialogue":999,"category":"가족","label":"Complex Reflection"},{"id":603,"text":"감정과 생각의 깊은 이유를 탐색하는 과정에서 많은 발견들이 있을 겁니다.","sourceDialogue":974,"category":"가족","label":"Complex Reflection"},{"id":604,"text":"감정과 의견을 솔직히 나누는 것이 중요함을 잘 알고 계시는군요.","sourceDialogue":991,"category":"가족","label":"General"},{"id":605,"text":"감정들이 혼란스러운 건 당연한 일일 수 있습니다.","sourceDialogue":446,"category":"자아·성격","label":"General"},{"id":606,"text":"감정을 구체적으로 이해하려는 노력은 문제를 해결해 나가는데 중요한 부분이 될 것입니다.","sourceDialogue":313,"category":"대인관계","label":"Complex Reflection"},{"id":607,"text":"감정을 숨기는 과정에서 허무함과 외로움을 경험하시는군요.","sourceDialogue":343,"category":"대인관계","label":"Complex Reflection"},{"id":608,"text":"감정을 숨기면서 느끼는 허무함과 외로움에도 불구하고, 그 방식이 바람직하지 않다는 것을 아시는군요.","sourceDialogue":343,"category":"대인관계","label":"Complex Reflection"},{"id":609,"text":"감정을 인정받는 것만으로도 가끔은 큰 위안이 됩니다.","sourceDialogue":116,"category":"정신건강","label":"General"},{"id":610,"text":"감정을 해석하는 과정에서 때로 오해가 생기기도 하지요.","sourceDialogue":143,"category":"정신건강","label":"General"},{"id":611,"text":"감정의 인식은 변화를 이루기 위한 중요한 요소 중 하나로 평가됩니다.","sourceDialogue":35,"category":"정신건강","label":"Give Information"},{"id":612,"text":"감정이 흘러넘칠 때 자신을 약하다고 생각하시는군요.","sourceDialogue":981,"category":"가족","label":"Complex Reflection"},{"id":613,"text":"객관성을 추구하며 현 상황을 더 분명히 이해하고자 하는 의지가 엿보이네요.","sourceDialogue":81,"category":"정신건강","label":"Complex Reflection"},{"id":614,"text":"객관적인 기준을 갖추고자 하는 것이 상황을 더 이해하고 싶은 마음에서 오는군요.","sourceDialogue":278,"category":"대인관계","label":"Complex Reflection"},{"id":615,"text":"건강한 대처 방법을 통해 자신의 감정 관리에 대한 능력을 향상시킬 수 있겠네요.","sourceDialogue":523,"category":"자아·성격","label":"Complex Reflection"},{"id":616,"text":"건강한 방향으로 나아가고자 하는 마음은 변화를 위한 중요한 원동력이 됩니다.","sourceDialogue":31,"category":"정신건강","label":"Complex Reflection"},{"id":617,"text":"걷기를 시작하고자 하는 의지가 있으시군요. 이런 생각을 하신 것 자체가 긍정적인 변화를 향한 좋은 시작이라고 생각됩니다.","sourceDialogue":538,"category":"자아·성격","label":"Affirm"},{"id":618,"text":"관계 속에서 진정성을 추구하시는 모습이 인상 깊습니다.","sourceDialogue":206,"category":"대인관계","label":"Affirm"},{"id":619,"text":"관계에서 겪는 어려움은 정말로 마음이 무거울 수 있겠어요.","sourceDialogue":155,"category":"정신건강","label":"Complex Reflection"},{"id":620,"text":"굉장히 의미 있는 대화를 통해 용기를 찾아가고 계시군요.","sourceDialogue":695,"category":"취업·진로","label":"Affirm"},{"id":621,"text":"구체적인 방향을 고민하시는 과정 자체가 변화로 나아가는 데 있어 중요한 부분입니다.","sourceDialogue":31,"category":"정신건강","label":"General"},{"id":622,"text":"그 두려움과 걱정이 상당히 부담스러울 수 있겠어요.","sourceDialogue":473,"category":"자아·성격","label":"Complex Reflection"},{"id":623,"text":"그 방법으로 감정을 진정시키기에는 부족함을 느끼셨군요.","sourceDialogue":965,"category":"가족","label":"General"},{"id":624,"text":"그 방식이 여러분의 현재 상황을 유지하는 데 도움이 된다고 느끼시는군요.","sourceDialogue":434,"category":"자아·성격","label":"General"},{"id":625,"text":"그 부분이 스스로에게도, 타인과의 관계에서도 중요하다고 느끼시는군요.","sourceDialogue":562,"category":"자아·성격","label":"Complex Reflection"},{"id":626,"text":"그 분야에서 경험을 쌓으며 스스로에 대해 더 알아가게 되실 거예요.","sourceDialogue":42,"category":"정신건강","label":"Complex Reflection"},{"id":627,"text":"그 불안감을 인식하시는 과정 자체가 중요한 발전이라고 할 수 있겠네요.","sourceDialogue":438,"category":"자아·성격","label":"General"},{"id":628,"text":"그 불안감이 상당한 부담감으로 다가오고 있군요.","sourceDialogue":239,"category":"대인관계","label":"Complex Reflection"},{"id":629,"text":"그 생각들로부터 벗어나려는 노력이 자신을 보호하려는 중요한 과정임을 알아차리셨군요.","sourceDialogue":329,"category":"대인관계","label":"Affirm"},{"id":630,"text":"그 싸움으로 인해 밤마다 마음이 편치 않으신 것 같아요.","sourceDialogue":989,"category":"가족","label":"Complex Reflection"},{"id":631,"text":"그 압박감을 느끼게 되는 과정에서 스스로에 대한 깊은 이해를 가지게 되셨을 거예요.","sourceDialogue":802,"category":"학업·고시","label":"General"},{"id":632,"text":"그 주변 사람들의 기대를 충족시키려는 노력이 상당히 힘들어 보이네요.","sourceDialogue":329,"category":"대인관계","label":"Complex Reflection"},{"id":633,"text":"그 활동을 통해 어려움 속에서도 소중한 자기표현의 방식을 찾으셨네요.","sourceDialogue":631,"category":"취업·진로","label":"Affirm"},{"id":634,"text":"그것 때문에 스스로를 다독이기가 어렵겠네요.","sourceDialogue":137,"category":"정신건강","label":"Complex Reflection"},{"id":635,"text":"그동안 겪으신 일들로 인해 쌓인 스트레스가 큰 부담이 되고 있다는 것을 알 수 있습니다.","sourceDialogue":56,"category":"정신건강","label":"Complex Reflection"},{"id":636,"text":"그동안 해결책을 찾고자 하는 마음가짐이 가지신 것으로 보여집니다.","sourceDialogue":189,"category":"정신건강","label":"General"},{"id":637,"text":"그들의 좋은 점에 더 집중하려는 노력이 성장의 발판이 될 거예요.","sourceDialogue":399,"category":"대인관계","label":"Affirm"},{"id":638,"text":"그러셨군요. 주변에 도움을 요청하기 어렵다는 감정은 때로는 해결 방법을 찾는 데 있어서도 도전이 될 수 있습니다.","sourceDialogue":346,"category":"대인관계","label":"Complex Reflection"},{"id":639,"text":"그러셨군요. 혼자서 결정을 내리고 행동으로 옮기셨네요.","sourceDialogue":161,"category":"정신건강","label":"General"},{"id":640,"text":"그런 감정은 많은 사람이 새로운 일을 시작할 때 자주 느끼곤 해요.","sourceDialogue":429,"category":"자아·성격","label":"General"},{"id":641,"text":"그런 감정을 겪고 계시다니 정말 힘드시겠어요.","sourceDialogue":128,"category":"정신건강","label":"General"},{"id":642,"text":"그런 감정을 겪으면서도 자신에 대해 깊이 고민하고 있군요.","sourceDialogue":96,"category":"정신건강","label":"Complex Reflection"},{"id":643,"text":"그런 감정을 겪으시며 상황을 이해하려고 노력하고 계시네요.","sourceDialogue":656,"category":"취업·진로","label":"Complex Reflection"},{"id":644,"text":"그런 경험으로 인해 스스로에 대해 많은 생각을 하게 되셨군요.","sourceDialogue":443,"category":"자아·성격","label":"General"},{"id":645,"text":"그런 경험을 하신다니 마음이 참 복잡하실 거예요.","sourceDialogue":566,"category":"자아·성격","label":"General"},{"id":646,"text":"그런 상태를 견디고 계시는 것, 대단히 힘들겠어요.","sourceDialogue":185,"category":"정신건강","label":"Complex Reflection"},{"id":647,"text":"그런 상황 속에서도 어려움을 털어놓으려 노력하시는군요.","sourceDialogue":165,"category":"정신건강","label":"Affirm"},{"id":648,"text":"그런 생각들이 마음속에 자리 잡고 있는 상황에서도 여기에 계신 걸 보면 큰 용기를 내셨네요.","sourceDialogue":899,"category":"학업·고시","label":"Affirm"},{"id":649,"text":"그런 생각이 들 때마다 스스로를 돌아보는 시간이 되시는군요.","sourceDialogue":546,"category":"자아·성격","label":"General"},{"id":650,"text":"그로 인해 마음이 많이 무겁게 느껴지시겠어요.","sourceDialogue":989,"category":"가족","label":"Complex Reflection"},{"id":651,"text":"그림을 통해 위안을 받는다는 것은 정서적으로 큰 도움이 될 수 있습니다.","sourceDialogue":407,"category":"자아·성격","label":"Give Information"},{"id":652,"text":"기분 전환을 위해 산책이나 운동으로 스스로 노력하고 계시군요.","sourceDialogue":777,"category":"취업·진로","label":"Affirm"},{"id":653,"text":"긴장감 속에서 자칫 잘못된 반응을 보이게 되는 상황이 심리적으로 부담스럽게 다가오고 있네요.","sourceDialogue":143,"category":"정신건강","label":"Complex Reflection"},{"id":654,"text":"노력에 비해 결과가 좋지 않아 실망스럽고 부담감도 느끼시는군요.","sourceDialogue":414,"category":"자아·성격","label":"Complex Reflection"},{"id":655,"text":"노력하는 과정 속에서 자신을 발검하고 이해하는 데 더 많은 통찰을 얻게 되실 것 같습니다.","sourceDialogue":683,"category":"취업·진로","label":"General"},{"id":656,"text":"노력하는 과정 자체가 이미 발전의 증거입니다.","sourceDialogue":214,"category":"대인관계","label":"Affirm"},{"id":657,"text":"느끼는 문제에 대해 근본적인 해결을 모색하시려는 용기가 대단합니다.","sourceDialogue":123,"category":"정신건강","label":"Affirm"},{"id":658,"text":"다른 사람들과의 관계에서 적극적으로 되고자 하는 욕구가 강하신 걸로 보입니다.","sourceDialogue":328,"category":"대인관계","label":"Affirm"},{"id":659,"text":"다른 사람들을 챙기고 존중하는 능력 외에도 자신의 장점이 더 구체화될 필요성을 느끼고 계시는군요.","sourceDialogue":795,"category":"취업·진로","label":"Complex Reflection"},{"id":660,"text":"다른 사람들의 말을 잘 듣고 공감하는 것이 자연스럽게 대화를 이끌고 긍정적인 에너지를 전달하는 첫걸음이 될 수 있겠네요.","sourceDialogue":365,"category":"대인관계","label":"Complex Reflection"},{"id":661,"text":"대중교통 전체가 이제는 편안함이 아닌 어려움의 대상이 되었네요.","sourceDialogue":529,"category":"자아·성격","label":"Complex Reflection"},{"id":662,"text":"대학 생활과 전공 선택에 대한 스트레스는 정말 힘들 수 있어요.","sourceDialogue":650,"category":"취업·진로","label":"General"},{"id":663,"text":"대화에서 긍정적인 말을 더 많이 하려고 하시는 건 사람들과의 관계 개선에 좋은 영향을 미칠 것입니다.","sourceDialogue":392,"category":"대인관계","label":"Affirm"},{"id":664,"text":"대화할 때 자연스럽게 생각을 표현하는 것에 대한 욕구가 강하다고 느끼시는군요.","sourceDialogue":71,"category":"정신건강","label":"Complex Reflection"},{"id":665,"text":"동생과의 관계 개선에 대한 고민을 공유해주셨군요.","sourceDialogue":956,"category":"가족","label":"General"},{"id":666,"text":"동호회 친구와의 공통 관심사를 통해 마음을 열고자 하는 단계에서 뜻깊은 연결점을 찾으셨군요.","sourceDialogue":315,"category":"대인관계","label":"Affirm"},{"id":667,"text":"동호회 활동을 통해 새로운 사람들과 자연스럽게 교류하고 싶으시군요.","sourceDialogue":161,"category":"정신건강","label":"Complex Reflection"},{"id":668,"text":"마음 속 깊은 곳에서 부터 평온을 되찾으려는 노력을 하고 계시는국요.","sourceDialogue":436,"category":"자아·성격","label":"Complex Reflection"},{"id":669,"text":"마음속에서는 가족과 소통하고 싶은 갈망이 있는데, 그 첫걸음을 어떻게 내딛어야 할지에 대한 확신이 서지 않는 상태로군요.","sourceDialogue":69,"category":"정신건강","label":"Complex Reflection"},{"id":670,"text":"마음에서 우러나는 행동이 변화로 이어질 수 있도록 서로 협력해 나가요.","sourceDialogue":288,"category":"대인관계","label":"General"},{"id":671,"text":"마음이 불안하고 괴로움을 느끼게 해서 잠들기가 어렵군요.","sourceDialogue":101,"category":"정신건강","label":"Complex Reflection"},{"id":672,"text":"모든 선택에 대해 의미를 찾지 못하고, 무엇을 선택해도 후회할 것 같아 앞으로 나아가기가 막막하신 것 같군요.","sourceDialogue":95,"category":"정신건강","label":"Complex Reflection"},{"id":673,"text":"무엇이 나아지기 위해 필요한지에 대한 방향성을 찾고자 하는 의지가 강하신 것 같습니다.","sourceDialogue":413,"category":"자아·성격","label":"General"},{"id":674,"text":"문제를 해결하기 위해 도전하는 용기가 있으셨네요.","sourceDialogue":76,"category":"정신건강","label":"Affirm"},{"id":675,"text":"미래에 대한 불안과 비교에서 오는 자신감의 부족을 겪고 계시네요.","sourceDialogue":26,"category":"정신건강","label":"Complex Reflection"},{"id":676,"text":"바꾸고 싶은 욕구와 현재의 부담 사이에서 고민하시는군요.","sourceDialogue":470,"category":"자아·성격","label":"Complex Reflection"},{"id":677,"text":"반려묘를 잃은 슬픔이 불안의 감정까지 다시 격화시켰군요.","sourceDialogue":115,"category":"정신건강","label":"Complex Reflection"},{"id":678,"text":"배려는 때로는 예상치 못한 어려움을 가져다주기도 하죠.","sourceDialogue":249,"category":"대인관계","label":"General"},{"id":679,"text":"배운 내용을 실제로 적용하며 점진적으로 개선해 나가려는 계획이 실력 향상에 큰 도움이 될 것입니다.","sourceDialogue":704,"category":"취업·진로","label":"Affirm"},{"id":680,"text":"벗어나고 싶은 마음이 있다는 것, 그것 자체가 중요한 인식입니다.","sourceDialogue":488,"category":"자아·성격","label":"General"},{"id":681,"text":"변화를 추구하시려는 의지가 있으시군요, 그것 자체가 이미 큰 용기입니다.","sourceDialogue":680,"category":"취업·진로","label":"Affirm"},{"id":682,"text":"변화를 향한 마음이 중요한 첫걸음이 됩니다.","sourceDialogue":503,"category":"자아·성격","label":"Complex Reflection"},{"id":683,"text":"변화에 대한 필요성은 인지하고 계시지만, 그 첫걸음을 어떻게 내딛어야 할지 막막함을 겪고 계시네요.","sourceDialogue":545,"category":"자아·성격","label":"Complex Reflection"},{"id":684,"text":"변화에 대한 필요성을 인식하고 계시면서도 현재 상황에서 벗어나기가 쉽지 않으신 것 같아요.","sourceDialogue":538,"category":"자아·성격","label":"Complex Reflection"},{"id":685,"text":"변화에 향해 나아가려는 용기가 보기 좋습니다.","sourceDialogue":621,"category":"취업·진로","label":"Affirm"},{"id":686,"text":"변화하는 자신의 욕구와 관심사를 인식하는 과정은 자기 이해의 중요한 부분입니다.","sourceDialogue":746,"category":"취업·진로","label":"General"},{"id":687,"text":"본인의 웰빙을 위해 노력하고 계시네요. 견고한 의지를 가지고 계십니다.","sourceDialogue":267,"category":"대인관계","label":"Affirm"},{"id":688,"text":"본인의 취미 생활과 친구들과의 시간을 중요시하려는 마음이 변화로 이어질 수 있는 긍정적인 신호입니다.","sourceDialogue":574,"category":"자아·성격","label":"Complex Reflection"},{"id":689,"text":"부담감으로 인해 자신을 몰아붙이고 계신 상황이시군요.","sourceDialogue":431,"category":"자아·성격","label":"Complex Reflection"},{"id":690,"text":"부담감이 관계를 더 어렵게 만들어, 멀어지게 하는 데 영향을 주고 있네요.","sourceDialogue":297,"category":"대인관계","label":"Complex Reflection"},{"id":691,"text":"부정적인 반응을 긍정적으로 바라보려는 노력이 정말 멋지십니다.","sourceDialogue":310,"category":"대인관계","label":"Affirm"},{"id":692,"text":"부정적인 상황에도 불구하고 변화를 추구하려는 당신의 결심이 대단합니다.","sourceDialogue":287,"category":"대인관계","label":"Affirm"},{"id":693,"text":"부족함을 느끼는 것은 모두에게 있는 감정이에요.","sourceDialogue":26,"category":"정신건강","label":"General"},{"id":694,"text":"불안에서 벗어나고 싶으신 마음이 있으시군요.","sourceDialogue":173,"category":"정신건강","label":"Complex Reflection"},{"id":695,"text":"불안한 감정을 마주하기보다는 멀어지려는 방법을 선택하고 계셨네요.","sourceDialogue":708,"category":"취업·진로","label":"Complex Reflection"},{"id":696,"text":"불안함과 회피하고 싶은 마음이 쌓여가고 계시는군요.","sourceDialogue":414,"category":"자아·성격","label":"Complex Reflection"},{"id":697,"text":"불필요한 책임감으로 인해 부담을 느끼고 계시는군요.","sourceDialogue":386,"category":"대인관계","label":"Complex Reflection"},{"id":698,"text":"사람들과의 관계 맺음과 모임이나 활동에 참여하는 것이 지금의 상황을 개선하는 데 도움이 될 것 같다고 느끼시는군요.","sourceDialogue":29,"category":"정신건강","label":"Complex Reflection"},{"id":699,"text":"사람들과의 관계에서 두려움 때문에 고립될까 염려하시는 마음이 크신 것 같습니다.","sourceDialogue":424,"category":"자아·성격","label":"Complex Reflection"},{"id":700,"text":"사람들과의 관계에서 인정받고 싶은 마음이 강하게 드러나고 있네요.","sourceDialogue":587,"category":"자아·성격","label":"Complex Reflection"},{"id":701,"text":"사람들과의 교류가 힘들어 자신감이 상당히 떨어지셨을 것 같네요.","sourceDialogue":392,"category":"대인관계","label":"Complex Reflection"},{"id":702,"text":"사람들과의 소통이 점차 부담으로 느껴지고 있는 것 같아요.","sourceDialogue":109,"category":"정신건강","label":"Complex Reflection"},{"id":703,"text":"사람들이 서로를 더 잘 이해하고 소통할 수 있는 분야의 직업을 탐색하는 과정은 분명 가치 있는 경험이 될 겁니다.","sourceDialogue":795,"category":"취업·진로","label":"General"},{"id":704,"text":"사람을 대하는 일로 인한 스트레스와 건강 악화가 큰 부담이 되고 계시네요.","sourceDialogue":148,"category":"정신건강","label":"Complex Reflection"},{"id":705,"text":"사랑받는다는 느낌을 받지 못할 때, 정말 힘들 수 있겠어요.","sourceDialogue":155,"category":"정신건강","label":"Complex Reflection"},{"id":706,"text":"사회생활에서 대인 관계 상황이 신경 쓰이고 부담되시는군요.","sourceDialogue":542,"category":"자아·성격","label":"Complex Reflection"},{"id":707,"text":"사회적 상황에 적극적으로 참여하려는 노력이 자신감을 키우는 데 도움이 되겠군요.","sourceDialogue":225,"category":"대인관계","label":"Complex Reflection"},{"id":708,"text":"사회적 상황에서 자신을 다른 사람들과 비교하실 때 더 큰 감정적 어려움을 겪고 계시는 것 같네요.","sourceDialogue":456,"category":"자아·성격","label":"Complex Reflection"},{"id":709,"text":"상대방의 이야기를 경청하고 입장을 고려하는 태도는 분명 대인관계에서 긍정적인 영향을 미치는 자세입니다.","sourceDialogue":247,"category":"대인관계","label":"Affirm"},{"id":710,"text":"상대방이 지칠까 봐 불안해하시는 마음이 크시군요.","sourceDialogue":543,"category":"자아·성격","label":"Complex Reflection"},{"id":711,"text":"상처 주고 싶지 않은 마음이 겉모습을 유지하려는 노력으로 이어지고 있네요.","sourceDialogue":556,"category":"자아·성격","label":"Complex Reflection"},{"id":712,"text":"상황을 개선하고자 하는 용기와 의지를 가지고 계시군요.","sourceDialogue":279,"category":"대인관계","label":"Affirm"},{"id":713,"text":"상황을 개선하고자 하는 의지가 있으시군요. 용기 내어 말씀해주셔서 감사합니다.","sourceDialogue":338,"category":"대인관계","label":"Affirm"},{"id":714,"text":"새로운 방법을 찾으려는 노력이 문제를 해결하는 데 도움이 될 수 있을 거예요.","sourceDialogue":445,"category":"자아·성격","label":"General"},{"id":715,"text":"새로운 사람들과의 관계 맺음에서 오는 부담감이 상당하신 것 같습니다.","sourceDialogue":368,"category":"대인관계","label":"Complex Reflection"},{"id":716,"text":"새로운 시도로 상황 개선에 도움이 될 것이라는 생각을 하고 계시네요.","sourceDialogue":21,"category":"정신건강","label":"Complex Reflection"},{"id":717,"text":"새로운 활동에 도전하는 게 부정적인 생각을 다스릴 방법을 찾는 데 도움이 된 모양이네요.","sourceDialogue":422,"category":"자아·성격","label":"Complex Reflection"},{"id":718,"text":"새벽이 될 때까지 기다리는 동안 마음은 더욱 조급해지겠군요.","sourceDialogue":193,"category":"정신건강","label":"Complex Reflection"},{"id":719,"text":"서로 이야기를 나누며 마음이 놓이셨다니 저도 기쁩니다.","sourceDialogue":518,"category":"자아·성격","label":"General"},{"id":720,"text":"서로의 경험을 나누며 이해의 폭을 넓히는 것은 성장하는 데 중요한 요소입니다.","sourceDialogue":225,"category":"대인관계","label":"General"},{"id":721,"text":"선택과 결정을 통해 자신이 진정 원하는 바를 조금씩 파악해 나가려는 고민이 느껴집니다.","sourceDialogue":357,"category":"대인관계","label":"Complex Reflection"},{"id":722,"text":"선택하신 길에 대해 깊이 고민하고 계시는 것 같군요.","sourceDialogue":555,"category":"자아·성격","label":"General"},{"id":723,"text":"선택하신 방법이 실제로 실행에 옮겨지길 바랍니다.","sourceDialogue":41,"category":"정신건강","label":"General"},{"id":724,"text":"성격은 때때로 우리의 선택에 영향을 미치곤 하지요.","sourceDialogue":589,"category":"자아·성격","label":"General"},{"id":725,"text":"성공적인 순간들을 기억하려는 노력이 현재의 어려움을 넘어서는 데 도움이 되겠네요.","sourceDialogue":890,"category":"학업·고시","label":"Affirm"},{"id":726,"text":"소통하는 방법을 통해 감정을 관리하고자 하는 생각은 남다른 접근이 될 수 있습니다.","sourceDialogue":110,"category":"정신건강","label":"General"},{"id":727,"text":"손상된 자신감을 회복하고 더 이상 상처받지 않기를 희망하며, 그 방향으로 나아갈 준비가 되어 있는 것 같군요.","sourceDialogue":244,"category":"대인관계","label":"Complex Reflection"},{"id":728,"text":"스스로를 진정시키는 방법에 대해 생각해 보셨네요.","sourceDialogue":586,"category":"자아·성격","label":"Complex Reflection"},{"id":729,"text":"스스로에 대한 기대가 높은 상황에서 압박감을 경험하고 계시네요.","sourceDialogue":494,"category":"자아·성격","label":"Complex Reflection"},{"id":730,"text":"스스로의 삶을 추구하고자 하는 간절함이 있으나 현 상황에서 그 목표에 다가가기 어려워 하시는군요.","sourceDialogue":990,"category":"가족","label":"Complex Reflection"},{"id":731,"text":"슬픔 속에서도 앞으로 나아가고 싶은 마음이 있는 것 같네요.","sourceDialogue":984,"category":"가족","label":"Complex Reflection"},{"id":732,"text":"실제 업무 흐름과 일상을 이해하며 자신이 어떻게 기여할 수 있을지 파악하려는 노력이 경험을 통해 실현될 것입니다.","sourceDialogue":602,"category":"취업·진로","label":"General"},{"id":733,"text":"실질적인 행동을 결정하는 과정이 어려울 수 있음을 이해합니다.","sourceDialogue":8,"category":"정신건강","label":"Complex Reflection"},{"id":734,"text":"실천할 수 있는 작은 방법을 찾아 매일 조금씩 실행해보기로 한 결정이 앞으로의 변화에 도움이 될 것입니다.","sourceDialogue":893,"category":"학업·고시","label":"Affirm"},{"id":735,"text":"아직 생각해보지 않았다는 건 앞으로 여러 가능성을 탐색할 여지가 있다는 의미일 수 있겠네요.","sourceDialogue":183,"category":"정신건강","label":"General"},{"id":736,"text":"아직 해결책을 찾지 못하셨지만, 무거운 마음에서 벗어나고 싶은 생각은 있으신 것 같네요.","sourceDialogue":962,"category":"가족","label":"Complex Reflection"},{"id":737,"text":"아침에 일어나기 힘든 상황과 항상 기운이 없다는 점이 많이 부담되시겠어요.","sourceDialogue":126,"category":"정신건강","label":"Complex Reflection"},{"id":738,"text":"안전과 행복을 느끼며 웃음 지을 수 있는 상황을 그림으로 그리시는 건 아주 좋은 시작이에요.","sourceDialogue":132,"category":"정신건강","label":"General"},{"id":739,"text":"압박감을 느낄 때 새로운 대처 방법을 모색하고 싶은 마음이 생기신 것 같네요.","sourceDialogue":455,"category":"자아·성격","label":"General"},{"id":740,"text":"어떤 날은 스스로에게 주어진 책임감을 무겁게 느끼시는군요.","sourceDialogue":477,"category":"자아·성격","label":"General"},{"id":741,"text":"어떤 변화를 시도하고 싶은지 고려하고 있는 과정을 통해 스스로 대해 깊이 생각해보고 계시군요.","sourceDialogue":567,"category":"자아·성격","label":"Complex Reflection"},{"id":742,"text":"어려운 상황 속에서도 문제를 해결하려는 의지를 보이시는군요. 정말 용기 있으십니다.","sourceDialogue":979,"category":"가족","label":"Affirm"},{"id":743,"text":"어려운 순간에도 조금씩 시도해 보려는 노력을 하고 계시군요.","sourceDialogue":19,"category":"정신건강","label":"Affirm"},{"id":744,"text":"엄마로 인한 스트레스가 피하고 싶은 마음과 과거의 기억들을 계속 되새기게 하고 있네요.","sourceDialogue":962,"category":"가족","label":"Complex Reflection"},{"id":745,"text":"엄마를 위해 헌신하시면서 자신에게 필요한 것들을 소홀히 하고 계시군요.","sourceDialogue":983,"category":"가족","label":"Complex Reflection"},{"id":746,"text":"엄마를 향한 사랑과 동시에 자신에게 느끼는 죄책감이 깊게 얽혀 있음을 인지하고 계시는군요.","sourceDialogue":229,"category":"대인관계","label":"Complex Reflection"},{"id":747,"text":"엄마에 대한 깊은 신경과 본인에 대한 엄격한 자책감 사이에서 고민하고 계시네요.","sourceDialogue":229,"category":"대인관계","label":"Complex Reflection"},{"id":748,"text":"에너지가 많이 딸리시고, 회복을 위한 시간도 부족한 상황이시군요.","sourceDialogue":148,"category":"정신건강","label":"Complex Reflection"},{"id":749,"text":"에너지를 찾기 위한 노력보다는 지금 상황에 대한 이해와 수용에 무게를 두고 계시는 것 같군요.","sourceDialogue":47,"category":"정신건강","label":"Complex Reflection"},{"id":750,"text":"연구와 지식을 탐구하는 과정이 여러분의 성장에 도움이 될 것입니다.","sourceDialogue":379,"category":"대인관계","label":"General"},{"id":751,"text":"연습을 통해 자신의 표현 방식을 발전시키려는 의지가 있으시군요.","sourceDialogue":534,"category":"자아·성격","label":"Affirm"},{"id":752,"text":"연습을 통해 점점 더 자연스러운 표현을 할 수 있게 될 것이라 믿습니다.","sourceDialogue":223,"category":"대인관계","label":"Complex Reflection"},{"id":753,"text":"와중에도 직면하는 것보다 감정을 피하는 쪽을 선택하시는군요.","sourceDialogue":544,"category":"자아·성격","label":"Complex Reflection"},{"id":754,"text":"외부 활동과 대인 관계에 대한 부담을 느끼고 계시군요.","sourceDialogue":77,"category":"정신건강","label":"Complex Reflection"},{"id":755,"text":"의미 있는 소통을 통해 자신의 감정과 생각이 온전히 전달되기를 바라시는군요.","sourceDialogue":312,"category":"대인관계","label":"Complex Reflection"},{"id":756,"text":"이 관계로 인해 크게 힘들어하시면서, 상황을 변화시키고자 하는 생각을 하고 계시는군요.","sourceDialogue":382,"category":"대인관계","label":"Complex Reflection"},{"id":757,"text":"이런 경험은 선택의 여지 없이 어려운 순간을 마주하는 것일 수 있습니다.","sourceDialogue":530,"category":"자아·성격","label":"General"},{"id":758,"text":"이런 상황에서 자신의 반응을 더 잘 이해하고 싶으시군요.","sourceDialogue":542,"category":"자아·성격","label":"Complex Reflection"},{"id":759,"text":"이런 순간을 통해 서로 간의 이해가 깊어지며 심리적 성장을 경험할 수 있을 거예요.","sourceDialogue":288,"category":"대인관계","label":"General"},{"id":760,"text":"이뤄낸 성과들을 떠올리며 기록하는 것이 도움이 될 겁니다.","sourceDialogue":697,"category":"취업·진로","label":"Affirm"},{"id":761,"text":"이야기를 듣고 조언을 해줄 때 필요로 하는 방식을 분명히 알고 계시군요.","sourceDialogue":982,"category":"가족","label":"General"},{"id":762,"text":"일상의 모든 활동이 부담감이 되어버린 것 같네요.","sourceDialogue":198,"category":"정신건강","label":"Complex Reflection"},{"id":763,"text":"일을 시작하기 전에 느끼는 그 부담감은 정말 크게 다가올 수 있어요.","sourceDialogue":545,"category":"자아·성격","label":"Complex Reflection"},{"id":764,"text":"잃어버린 흥미를 찾기 위해 자신에게 맞는 것을 탐색하고자 하는 과정이 필요하군요.","sourceDialogue":145,"category":"정신건강","label":"General"},{"id":765,"text":"자기 자신에 대한 신뢰가 줄어들고 가치를 느끼지 못하는 경험이 앞서 말씀하신 힘든 상황들을 더 어렵게 만들고 있네요.","sourceDialogue":102,"category":"정신건강","label":"Complex Reflection"},{"id":766,"text":"자신감을 찾는 과정에서 불확실성을 느끼시는 건 자연스러운 일입니다.","sourceDialogue":696,"category":"취업·진로","label":"General"},{"id":767,"text":"자신에 대한 긍정적인 시각이 변화의 좋은 출발점이 될 수 있겠네요.","sourceDialogue":464,"category":"자아·성격","label":"General"},{"id":768,"text":"자신에 대한 믿음이 부족하시면서도, 무언가를 시작하고 싶은 마음이 교차하고 있네요.","sourceDialogue":425,"category":"자아·성격","label":"Complex Reflection"},{"id":769,"text":"자신을 고립시키고자 하는 경향이 점점 더 자연스러워지고 있음을 느끼시는군요.","sourceDialogue":270,"category":"대인관계","label":"Complex Reflection"},{"id":770,"text":"자신을 되돌아보는 과정 속에서 새로운 이해와 인식을 발견하는 게 가능해 보입니다.","sourceDialogue":222,"category":"대인관계","label":"Complex Reflection"},{"id":771,"text":"자신을 믿고 도전하는 과정에서 얻게 될 경험들이 분명히 도움이 될 거예요.","sourceDialogue":260,"category":"대인관계","label":"Complex Reflection"},{"id":772,"text":"자신을 사랑하는 방법을 찾고자 하는 고민이 깊으신 것 같네요.","sourceDialogue":496,"category":"자아·성격","label":"General"},{"id":773,"text":"자신을 탓하며 자책감에 사로잡혀 계시는군요.","sourceDialogue":1,"category":"정신건강","label":"Complex Reflection"},{"id":774,"text":"자신의 노력을 이해시키고 싶어도 가족에게 어떻게 전달해야 할지 막막함을 느끼고 계시는군요.","sourceDialogue":798,"category":"취업·진로","label":"Complex Reflection"},{"id":775,"text":"자신의 문제를 해결하고자 하는 의지가 있으시군요. 용기 있으십니다.","sourceDialogue":127,"category":"정신건강","label":"Affirm"},{"id":776,"text":"자신의 의견을 표현하고 요구를 거절하는 것이 부담스럽게 느껴지는군요.","sourceDialogue":495,"category":"자아·성격","label":"Complex Reflection"},{"id":777,"text":"자신이 가진 능력과 성향을 이해하려는 과정이 쉽지 않을 수 있군요.","sourceDialogue":507,"category":"자아·성격","label":"Complex Reflection"},{"id":778,"text":"자신이 남들보다 부족하다고 느끼시는 상황이 상당히 부담스러우시군요.","sourceDialogue":58,"category":"정신건강","label":"Complex Reflection"},{"id":779,"text":"자신이 얼마나 힘들어하는지 파악하기 어려우시군요.","sourceDialogue":179,"category":"정신건강","label":"Complex Reflection"},{"id":780,"text":"자신이 좋아하고 싫어하는 것을 글로 정리하는 것도 자기 이해를 넓히는 훌륭한 방법이에요.","sourceDialogue":335,"category":"대인관계","label":"Give Information"},{"id":781,"text":"자아실현을 위해 무엇을 좋아하고 잘하는지 알고 싶고, 이를 통해 인간관계도 편안하게 맺고 싶은데 그 시작점을 찾기 어려워하시는군요.","sourceDialogue":511,"category":"자아·성격","label":"Complex Reflection"},{"id":782,"text":"작은 시도에서부터 시작하려는 계획이 긍정적인 변화로 이어질 것입니다.","sourceDialogue":243,"category":"대인관계","label":"Affirm"},{"id":783,"text":"잠 못 이루는 밤이 상당히 힘들게 하고 계시겠어요.","sourceDialogue":150,"category":"정신건강","label":"Complex Reflection"},{"id":784,"text":"잠드는 것이 힘들고 악몽 때문에 깨는 것이 낮 시간의 집중력에도 영향을 미치고 있네요.","sourceDialogue":149,"category":"정신건강","label":"Complex Reflection"},{"id":785,"text":"적응력과 회복력을 키우기 위한 의지를 가지고 계시군요.","sourceDialogue":281,"category":"대인관계","label":"General"},{"id":786,"text":"적절한 존중을 받지 못함으로써 자존감에 영향을 받고 계시네요.","sourceDialogue":256,"category":"대인관계","label":"Complex Reflection"},{"id":787,"text":"정리된 환경과 체계적인 계획에도 불구하고 마음이 다른 곳으로 향하는 것에 대해 큰 답답함을 느끼고 계시네요.","sourceDialogue":967,"category":"가족","label":"Complex Reflection"},{"id":788,"text":"정보의 바다에서 필요한 것을 찾는 일은 종종 어려울 수 있어요.","sourceDialogue":81,"category":"정신건강","label":"General"},{"id":789,"text":"정신건강 전문가들은 변화를 갈망하는 마음이 있다면 그것이 변화의 첫걸음이 될 수 있다고 말합니다.","sourceDialogue":88,"category":"정신건강","label":"Give Information"},{"id":790,"text":"조금씩 밖으로 나가보려는 시도가 주는 경험이 도움이 될 겁니다.","sourceDialogue":730,"category":"취업·진로","label":"Affirm"},{"id":791,"text":"조용한 공원이나 따뜻한 햇볕을 만끽할 때 마음이 가벼워지는 걸 찾으셨네요.","sourceDialogue":126,"category":"정신건강","label":"General"},{"id":792,"text":"주변 사람들과의 관계에 변화가 생기면서 느끼는 불안함이 상당하신 것 같군요.","sourceDialogue":424,"category":"자아·성격","label":"Complex Reflection"},{"id":793,"text":"진정으로 받아들여지는 느낌을 원하시는군요, 서로의 관심사를 공유하며 자연스러운 대화를 통해 이루고 싶으신 것 같습니다.","sourceDialogue":349,"category":"대인관계","label":"Complex Reflection"},{"id":794,"text":"취미활동이나 동아리활동을 통해 새로운 관계를 맺고 그리움과 외로움을 다루는 방법을 모색하고 계시는군요.","sourceDialogue":125,"category":"정신건강","label":"Complex Reflection"},{"id":795,"text":"친구들과의 활발한 교류를 목격할 때마다 관계의 부재감에 외로움을 느끼시는 것 같네요.","sourceDialogue":351,"category":"대인관계","label":"Complex Reflection"},{"id":796,"text":"친구들의 기분을 맞추기 위해 자신을 절제하면서, 꽤 큰 외로움과 힘듦을 겪고 계시네요.","sourceDialogue":215,"category":"대인관계","label":"Complex Reflection"},{"id":797,"text":"친구들의 부담을 함께 나누되, 자신의 한계를 지키고자 하는 균형을 찾으려 하시는군요.","sourceDialogue":52,"category":"정신건강","label":"Complex Reflection"},{"id":798,"text":"친구와의 관계를 건강하게 유지하고자 하는 강한 의지를 보여주셨네요.","sourceDialogue":373,"category":"대인관계","label":"Affirm"},{"id":799,"text":"친구와의 변화된 관계로 인해 느끼시는 불안함과 초조함이 많이 쌓이셨군요.","sourceDialogue":27,"category":"정신건강","label":"Complex Reflection"},{"id":800,"text":"타이머를 설정하여 단시간 집중을 시도하는 것으로 스스로에게 집중력 증진 기회를 주시려는 군요.","sourceDialogue":460,"category":"자아·성격","label":"General"},{"id":801,"text":"표현에 대한 두려움이 생활 전반에 걸쳐 부담을 주고 계시네요.","sourceDialogue":585,"category":"자아·성격","label":"Complex Reflection"},{"id":802,"text":"해결책을 찾기 위한 생각에 몰두하고 계시지만, 혼자서는 해결 방법을 찾기가 쉽지 않으신 것 같아요.","sourceDialogue":111,"category":"정신건강","label":"Complex Reflection"},{"id":803,"text":"현재의 두려움이 상당히 부담이 되고 계시다는 것을 느낄 수 있습니다.","sourceDialogue":10,"category":"정신건강","label":"Complex Reflection"},{"id":804,"text":"혼자 있는 시간에 감정이 더 커져서 고립감을 느끼시는 거군요.","sourceDialogue":226,"category":"대인관계","label":"Complex Reflection"},{"id":805,"text":"혼자만의 시간과 공간을 갖지 못해 스트레스를 받고 계시는군요.","sourceDialogue":964,"category":"가족","label":"Complex Reflection"},{"id":806,"text":"혼자만의 시간에 익숙해져 가는 과정 속에서 어떤 감정이나 생각이 드는지를 조심스레 탐색해 오셨군요.","sourceDialogue":270,"category":"대인관계","label":"Complex Reflection"},{"id":807,"text":"화상 통화나 전화로 잠시나마 해소되는 것처럼 보이는 그리움과 외로움이 실제로는 더 크게 느껴지고 계시는 것 같네요.","sourceDialogue":125,"category":"정신건강","label":"Complex Reflection"},{"id":808,"text":"휴학을 하고 스스로에게 시간을 주는 등 상황을 개선하기 위해 노력해 오셨군요.","sourceDialogue":650,"category":"취업·진로","label":"Affirm"},{"id":809,"text":"흥미와 어울림을 기준으로 결정하려는 노력을 하고 계시는군요.","sourceDialogue":403,"category":"자아·성격","label":"Affirm"},{"id":810,"text":"가까운 관계를 원하는 한편에서는 그로 인한 불안감도 겪고 계시는군요.","sourceDialogue":83,"category":"정신건강","label":"Complex Reflection"},{"id":811,"text":"가깝지 않은 사람들의 기준에 맞추기 위해 스스로를 압박하는 상황에 대해 의문을 가지고 계시네요.","sourceDialogue":250,"category":"대인관계","label":"Complex Reflection"},{"id":812,"text":"가능성을 탐색하고자 하는 마음가짐은 큰 자산이 될 것입니다.","sourceDialogue":740,"category":"취업·진로","label":"Affirm"},{"id":813,"text":"가볍게 산책을 시작하는 것이 변화를 위한 좋은 방법일 수 있겠네요.","sourceDialogue":444,"category":"자아·성격","label":"General"},{"id":814,"text":"가족 구성원이 서로 바로 이야기할 수 있는 방안을 모색하고 싶어 하시는군요.","sourceDialogue":985,"category":"가족","label":"Complex Reflection"},{"id":815,"text":"가족들에게 긍정적인 영향을 주고자 하는 마음이 깊으시군요.","sourceDialogue":262,"category":"대인관계","label":"Complex Reflection"},{"id":816,"text":"가족의 기대를 만족시키고자 하는 압박감이 스스로를 실망시키는 원인이 되고 있네요.","sourceDialogue":798,"category":"취업·진로","label":"Complex Reflection"},{"id":817,"text":"갈등을 겪으면서도 본인의 길을 찾고자 하는 고민이 의미 있는 여정이 되고 있군요.","sourceDialogue":493,"category":"자아·성격","label":"Complex Reflection"},{"id":818,"text":"감정 기복이 예전과 비교해 확연히 느껴지는 변화가 있으신 것 같군요.","sourceDialogue":5,"category":"정신건강","label":"Complex Reflection"},{"id":819,"text":"감정과 그에 따른 행동이나 말이 어떻게 상호작용하는지 관찰하는 과정은 매우 심오한 인식을 가져다줄 것입니다.","sourceDialogue":134,"category":"정신건강","label":"Complex Reflection"},{"id":820,"text":"감정과 생각을 글로 표현하며 자신을 명확히 인지하는 과정이 깊은 인사이트를 제공했군요.","sourceDialogue":471,"category":"자아·성격","label":"Complex Reflection"},{"id":821,"text":"감정과 생각을 정리하겠다는 결정을 내리신 것, 신중하십니다.","sourceDialogue":629,"category":"취업·진로","label":"Affirm"},{"id":822,"text":"감정은 사람마다 다르게 나타나고, 그것을 느끼는 것이 정상입니다.","sourceDialogue":230,"category":"대인관계","label":"General"},{"id":823,"text":"감정을 관리할 방법을 찾는 것에 대한 불확실성이 있으시네요.","sourceDialogue":178,"category":"정신건강","label":"Complex Reflection"},{"id":824,"text":"감정을 다루고 싶은 의지가 중요한 걸음이 되겠군요.","sourceDialogue":85,"category":"정신건강","label":"General"},{"id":825,"text":"감정을 솔직하게 공유하는 것은 관계를 깊게 하는데 중요한 역할을 합니다.","sourceDialogue":383,"category":"대인관계","label":"Give Information"},{"id":826,"text":"감정을 인식하고 다루려 노력하는 과정에서 많은 에너지가 소모되는 것 같군요.","sourceDialogue":539,"category":"자아·성격","label":"Complex Reflection"},{"id":827,"text":"감정을 있는 그대로 전달하기 위한 방법을 생각해보는 것은 소통의 질을 높이는 데 중요한 점입니다.","sourceDialogue":314,"category":"대인관계","label":"General"},{"id":828,"text":"감정을 정확히 인지하고 표현하는 것이 어렵지만, 그것이 중요함을 아시고 상대방에게 제대로 전달하고 싶은 마음이 크시군요.","sourceDialogue":275,"category":"대인관계","label":"Complex Reflection"},{"id":829,"text":"감정을 제어하는 데 어려움을 겪으면서 인간관계에도 부정적인 영향을 받고 계시네요.","sourceDialogue":238,"category":"대인관계","label":"Complex Reflection"},{"id":830,"text":"감정을 직면하며 생각에 잠기시는 시간이 본인에게 중요한 순간임을 알 수 있습니다.","sourceDialogue":26,"category":"정신건강","label":"Complex Reflection"},{"id":831,"text":"감정을 표현하는 일이 혼란스러우신 것 같아요.","sourceDialogue":442,"category":"자아·성격","label":"Complex Reflection"},{"id":832,"text":"감정의 롤러코스터를 경험하는 것은 아주 큰 도전이 될 수 있어요.","sourceDialogue":19,"category":"정신건강","label":"Complex Reflection"},{"id":833,"text":"감정의 혼란 속에서 어떤 결정을 내려야 할지 방황하고 계시네요.","sourceDialogue":578,"category":"자아·성격","label":"Complex Reflection"},{"id":834,"text":"감정이 솟구치는 순간에 자제력을 잃어버리는 것에 대해 큰 어려움을 겪고 계시는군요.","sourceDialogue":971,"category":"가족","label":"Complex Reflection"},{"id":835,"text":"갑작스러운 감정의 변화에 혼란스러움을 느끼시는군요.","sourceDialogue":564,"category":"자아·성격","label":"Complex Reflection"},{"id":836,"text":"개인의 성장과 발전을 위해 새로운 정보를 찾고 학습하는 것은 매우 가치 있는 일입니다.","sourceDialogue":379,"category":"대인관계","label":"General"},{"id":837,"text":"거짓말이 일상에서 깊이 자리 잡아서 진실을 말하는 것이 큰 부담이 되고 계시는군요.","sourceDialogue":468,"category":"자아·성격","label":"Complex Reflection"},{"id":838,"text":"걱정과 불안이 클 때도 있지만, 그럼에도 불구하고 스스로를 긍정적으로 바라볼 수 있는 순간이 있다는 것이 중요해요.","sourceDialogue":681,"category":"취업·진로","label":"Complex Reflection"},{"id":839,"text":"건강을 챙기고 식습관을 개선하려는 노력이 현재의 어려움을 극복하는 데 도움이 될 것임을 인식하고 계시네요.","sourceDialogue":444,"category":"자아·성격","label":"Complex Reflection"},{"id":840,"text":"결과물을 통해 뿌듯함을 느끼신다니 진정으로 가치 있는 경험을 하고 계신 것 같아요.","sourceDialogue":761,"category":"취업·진로","label":"Affirm"},{"id":841,"text":"결국 밤이 되면 편안함을 느끼기보다는 큰 두려움과 맞닥뜨리고 계시는군요.","sourceDialogue":193,"category":"정신건강","label":"Complex Reflection"},{"id":842,"text":"계획하신 활동을 통해 원하시는 변화가 생기기를 바랍니다.","sourceDialogue":184,"category":"정신건강","label":"General"},{"id":843,"text":"고립될까 봐 걱정되는 마음과 동시에 사람들과의 교류를 피하고 싶은 상황이 상충되고 있네요.","sourceDialogue":533,"category":"자아·성격","label":"Complex Reflection"},{"id":844,"text":"고민을 정리하려는 노력이 여러분을 성장시키고 있어요.","sourceDialogue":767,"category":"취업·진로","label":"Affirm"},{"id":845,"text":"고민의 시작도 성장으로 이어지는 중요한 부분이 됩니다.","sourceDialogue":570,"category":"자아·성격","label":"General"},{"id":846,"text":"고민이 많은 상황 속에서도 해결책을 찾고자 하는 노력이 느껴집니다.","sourceDialogue":227,"category":"대인관계","label":"General"},{"id":847,"text":"고백한 후에도 여전히 죄책감을 느끼고 계시는군요.","sourceDialogue":331,"category":"대인관계","label":"Complex Reflection"},{"id":848,"text":"공유하고자 하는 마음이 커지신 것, 이는 중요한 인식입니다.","sourceDialogue":28,"category":"정신건강","label":"Complex Reflection"},{"id":849,"text":"공통된 해결방법에 대한 확신이 서지 않으면서도 근본적인 변화에 대한 고민이 있다는 것을 느끼시는군요.","sourceDialogue":955,"category":"가족","label":"Complex Reflection"},{"id":850,"text":"과거에 대한 후회와 자책에서 벗어나 평온함을 찾고자 하시는군요.","sourceDialogue":444,"category":"자아·성격","label":"Complex Reflection"},{"id":851,"text":"과거의 경험이 새로운 환경에서의 관계 형성에 대한 불안을 증폭시키고 있네요.","sourceDialogue":349,"category":"대인관계","label":"Complex Reflection"},{"id":852,"text":"과거의 경험이 소중한 인간 관계를 맺는 데 계속 어려움을 주고 있군요.","sourceDialogue":372,"category":"대인관계","label":"Complex Reflection"},{"id":853,"text":"과거의 경험이 현재의 마음상태에도 영향을 미칠 수 있다는 걸 잘 아시는군요.","sourceDialogue":490,"category":"자아·성격","label":"General"},{"id":854,"text":"과거의 관계에 매여있지 않고 현재에 살아가기 위해 새로운 경험에 집중하고 싶어하는 마음이 있으시군요.","sourceDialogue":138,"category":"정신건강","label":"Complex Reflection"},{"id":855,"text":"교류하는 것이 외로움을 느끼게 하는 중요한 요인이 되고 있네요.","sourceDialogue":351,"category":"대인관계","label":"Complex Reflection"},{"id":856,"text":"구체적인 방법은 아직 모르시지만 변화를 추구하려는 용기를 가지고 계시군요.","sourceDialogue":21,"category":"정신건강","label":"Complex Reflection"},{"id":857,"text":"구체적인 방법을 찾으려는 노력은 문제 해결로 향하는 중요한 단계입니다.","sourceDialogue":568,"category":"자아·성격","label":"Affirm"},{"id":858,"text":"구체적인 활동이나 경험을 통해 자신에 대해 더 깊이 이해할 수 있는 기회가 될지도 모릅니다.","sourceDialogue":641,"category":"취업·진로","label":"General"},{"id":859,"text":"그 두 감정 사이에서 많은 갈등을 겪고 계시는군요.","sourceDialogue":83,"category":"정신건강","label":"General"},{"id":860,"text":"그 분야를 찾아가는 과정에서 본인만의 속도를 존중하는 것이 중요합니다.","sourceDialogue":762,"category":"취업·진로","label":"General"},{"id":861,"text":"그 분야에 대해 더 배우려는 노력이 이후의 경험에 큰 도움이 될 겁니다.","sourceDialogue":724,"category":"취업·진로","label":"General"},{"id":862,"text":"그 사이에서 고민하는 것은 쉽지 않은 일이실 거예요.","sourceDialogue":19,"category":"정신건강","label":"General"},{"id":863,"text":"그 상태로 인해 많은 생각과 감정을 겪고 계시겠어요.","sourceDialogue":558,"category":"자아·성격","label":"Complex Reflection"},{"id":864,"text":"그 스트레스가 학원 수업의 내용 때문인지, 아니면 다른 요인 때문인지에 대해 많이 고민하고 계시겠네요.","sourceDialogue":9,"category":"정신건강","label":"General"},{"id":865,"text":"그 일로 인한 자책감이 여전히 크신 것 같네요.","sourceDialogue":252,"category":"대인관계","label":"Complex Reflection"},{"id":866,"text":"그 팀원과 마주칠 때마다 느끼는 부담감이 꽤 큰 스트레스로 작용하고 있네요.","sourceDialogue":381,"category":"대인관계","label":"Complex Reflection"},{"id":867,"text":"그것에 대해 고민을 하시는 것 자체가 깊은 성찰이 필요한 문제임을 보여주네요.","sourceDialogue":410,"category":"자아·성격","label":"General"},{"id":868,"text":"그동안 본인의 감정을 상당히 깊게 되돌아보셨군요.","sourceDialogue":565,"category":"자아·성격","label":"General"},{"id":869,"text":"그동안 사람들과의 관계 속에서 겪는 감정의 변화가 쉽지 않으셨군요.","sourceDialogue":341,"category":"대인관계","label":"Complex Reflection"},{"id":870,"text":"그동안 선택의 순간마다 심사숙고하며 결정을 내리려 노력해 오셨군요.","sourceDialogue":623,"category":"취업·진로","label":"Affirm"},{"id":871,"text":"그러셨군요. 그런 감정은 종종 우리 모두에게 찾아오곤 해요.","sourceDialogue":47,"category":"정신건강","label":"General"},{"id":872,"text":"그러셨군요. 스스로에 대한 반성은 성장하기 위한 과정일 수 있어요.","sourceDialogue":525,"category":"자아·성격","label":"Complex Reflection"},{"id":873,"text":"그러실 수 있죠. 변화하는 과정에서 그런 생각이 들기도 합니다.","sourceDialogue":426,"category":"자아·성격","label":"General"},{"id":874,"text":"그런 감정을 겪는 것은 상당히 힘든 일이죠.","sourceDialogue":21,"category":"정신건강","label":"Complex Reflection"},{"id":875,"text":"그런 감정을 겪으시면서 여러가지를 느끼고 고민하셨을 거에요.","sourceDialogue":315,"category":"대인관계","label":"Complex Reflection"},{"id":876,"text":"그런 감정을 느끼신다면, 본인의 업무 스타일을 인식하는 데에 상당한 시간을 할애하셨겠군요.","sourceDialogue":451,"category":"자아·성격","label":"General"},{"id":877,"text":"그런 감정을 인정하시는 것이 중요한 걸음이 됩니다.","sourceDialogue":697,"category":"취업·진로","label":"Affirm"},{"id":878,"text":"그런 감정이야말로 추구하는 바를 위해 노력할 가치가 있겠군요.","sourceDialogue":609,"category":"취업·진로","label":"General"},{"id":879,"text":"그런 경험들로 인해 제법 힘들어하고 계시는군요.","sourceDialogue":195,"category":"정신건강","label":"Complex Reflection"},{"id":880,"text":"그런 경험은 자기 자신에 대해 더 깊이 생각하게 만들곤 합니다.","sourceDialogue":517,"category":"자아·성격","label":"General"},{"id":881,"text":"그런 답답함을 호소하시는 걸 보니 일상에 새로움을 찾고 싶은 마음이 있으신 것 같네요.","sourceDialogue":184,"category":"정신건강","label":"Complex Reflection"},{"id":882,"text":"그런 상황들이 본인에게 큰 부담으로 다가오는군요.","sourceDialogue":485,"category":"자아·성격","label":"Complex Reflection"},{"id":883,"text":"그런 상황에서는 마음이 많이 무거울 수 있겠어요.","sourceDialogue":70,"category":"정신건강","label":"Complex Reflection"},{"id":884,"text":"그런 상황에서도 꾸준히 자신을 돌아보려는 시도가 중요해요.","sourceDialogue":187,"category":"정신건강","label":"General"},{"id":885,"text":"그런 생각과 감정이 아주 자연스러운 과정이라는 걸 알게 되셨군요.","sourceDialogue":884,"category":"학업·고시","label":"General"},{"id":886,"text":"그런 생각이 드셨을 때 느끼시는 감정이 굉장히 복잡하실 것 같아요.","sourceDialogue":18,"category":"정신건강","label":"Complex Reflection"},{"id":887,"text":"그런 생각이 들 때마다 스스로를 돌아보는 시간이 되었군요.","sourceDialogue":225,"category":"대인관계","label":"General"},{"id":888,"text":"그런 생각이 본인에게 많은 부담을 주고 있겠군요.","sourceDialogue":65,"category":"정신건강","label":"Complex Reflection"},{"id":889,"text":"그런 생각이 자주 드는군요. 다른 사람의 시선을 의식하게 되는 것은 자연스러운 일입니다.","sourceDialogue":371,"category":"대인관계","label":"Complex Reflection"},{"id":890,"text":"글쓰기를 통해 자신의 감정을 탐색하고 싶으신 모습이 보여요.","sourceDialogue":224,"category":"대인관계","label":"Complex Reflection"},{"id":891,"text":"기록을 통해 자신의 생각과 감정을 정리하고자 하시는군요.","sourceDialogue":596,"category":"자아·성격","label":"Complex Reflection"},{"id":892,"text":"기분이 내키지 않을 때 사회적 상황이 더욱 부담스럽게 느껴지시는 것 같습니다.","sourceDialogue":271,"category":"대인관계","label":"Complex Reflection"},{"id":893,"text":"깊은 잠을 자지 못하는 문제가 계속되면서 많이 지치셨겠어요.","sourceDialogue":24,"category":"정신건강","label":"Complex Reflection"},{"id":894,"text":"낙관적으로 자신을 바라보게 되는 계기가 되길 바랍니다.","sourceDialogue":187,"category":"정신건강","label":"General"},{"id":895,"text":"남에게 도움을 주려는 성향 때문에 본인이 어려움을 겪고 계시는군요.","sourceDialogue":449,"category":"자아·성격","label":"Complex Reflection"},{"id":896,"text":"노력과 과정을 인정받으며 지지를 받기를 희망하시는군요.","sourceDialogue":393,"category":"대인관계","label":"Affirm"},{"id":897,"text":"노력이 인정받지 못한다고 느끼시며 이로 인해 더 큰 외로움과 소외감을 경험하고 계시는군요.","sourceDialogue":393,"category":"대인관계","label":"Complex Reflection"},{"id":898,"text":"노력해 나가려는 의지를 가지고 계시네요. 상당히 용기 있는 모습입니다.","sourceDialogue":824,"category":"학업·고시","label":"Affirm"},{"id":899,"text":"다른 사람의 태도 때문에 불안함을 느끼며 이는 직장 내에서의 관계에 큰 영향을 주고 있군요.","sourceDialogue":91,"category":"정신건강","label":"Complex Reflection"},{"id":900,"text":"답답함을 느끼시면서도 상황을 개선하고 싶은 마음이 있으신 것 같습니다.","sourceDialogue":16,"category":"정신건강","label":"Complex Reflection"},{"id":901,"text":"대인관계는 인생에서 크게 영향을 주는 부분이기에 고민이 많으셨을 것 같습니다.","sourceDialogue":217,"category":"대인관계","label":"General"},{"id":902,"text":"대화에 있어 타인의 반응이 불안을 느끼게 하는 중요한 요소라는 게 드러나네요.","sourceDialogue":543,"category":"자아·성격","label":"Complex Reflection"},{"id":903,"text":"대화의 부담감이 커지면서 사회적 상황에 대한 우려가 깊어지고 계시는 것 같네요.","sourceDialogue":336,"category":"대인관계","label":"Complex Reflection"},{"id":904,"text":"대화하는 것이 어려움으로 인해 외로움을 종종 느끼시는군요.","sourceDialogue":414,"category":"자아·성격","label":"Complex Reflection"},{"id":905,"text":"더 나은 사람이 되고자 하는 마음이 강한 동기 부여가 되고 있습니다.","sourceDialogue":180,"category":"정신건강","label":"Complex Reflection"},{"id":906,"text":"도움을 줄 때마다 상처받는 경험이 신뢰를 잃게 만들고, 그로 인해 타인과의 거리를 두게 되었국요.","sourceDialogue":219,"category":"대인관계","label":"Complex Reflection"},{"id":907,"text":"도움을 찾으며 접근 방법을 모색하는 것은 현명한 판단입니다.","sourceDialogue":865,"category":"학업·고시","label":"Affirm"},{"id":908,"text":"도전해보려는 용기를 가지신 것이 인상 깊습니다.","sourceDialogue":648,"category":"취업·진로","label":"Affirm"},{"id":909,"text":"마음 속에 많은 생각과 감정을 갖고 계시군요.","sourceDialogue":218,"category":"대인관계","label":"Complex Reflection"},{"id":910,"text":"마음속에는 변화를 위한 갈망이 있는데, 어디서부터 시작해야 할지 판단하기 어려운 상태이시군요.","sourceDialogue":164,"category":"정신건강","label":"Complex Reflection"},{"id":911,"text":"마음을 위한 취미 활동은 정서적 안정을 가져오는 데 도움이 될 것입니다.","sourceDialogue":768,"category":"취업·진로","label":"Give Information"},{"id":912,"text":"말씀을 나누며 마음이 가벼워지셨다니 저도 기쁘네요.","sourceDialogue":284,"category":"대인관계","label":"General"},{"id":913,"text":"모든 것이 버거울 정도로 마음이 무겁고, 어려움을 겪고 계시는 상황임을 이해합니다.","sourceDialogue":706,"category":"취업·진로","label":"Complex Reflection"},{"id":914,"text":"모든 문제가 겹쳤을 때의 부담감을 크게 느끼고 계신 것 같습니다.","sourceDialogue":995,"category":"가족","label":"Complex Reflection"},{"id":915,"text":"모든 일이 잘못될 것이라는 생각이 일상생활 전반에 걸쳐 부담을 주고 있군요.","sourceDialogue":488,"category":"자아·성격","label":"Complex Reflection"},{"id":916,"text":"목표 설정에 앞서 자신의 현재 상태, 가치, 그리고 중요하게 생각하는 것들을 명확히 하는 과정이 필요합니다.","sourceDialogue":735,"category":"취업·진로","label":"Give Information"},{"id":917,"text":"무기력함의 반복에서 벗어나려는 마음이 강하신 것 같습니다.","sourceDialogue":75,"category":"정신건강","label":"Complex Reflection"},{"id":918,"text":"문제를 깊게 이해하려는 노력은 해결책을 찾아가는 과정에서 중요한 역할을 합니다.","sourceDialogue":35,"category":"정신건강","label":"Give Information"},{"id":919,"text":"문제를 해결하고자 하는 의지가 생기셨다니, 진지하게 자신의 상황을 바라보고 계시네요.","sourceDialogue":31,"category":"정신건강","label":"Affirm"},{"id":920,"text":"문제를 해결하기 위해 소통을 선택하신 것은 현명한 결정입니다.","sourceDialogue":279,"category":"대인관계","label":"Affirm"},{"id":921,"text":"문제를 해결하기 위해 적극적으로 행동하려는 용기가 대단하시네요.","sourceDialogue":322,"category":"대인관계","label":"Affirm"},{"id":922,"text":"미래에 대한 불안정성과 현재의 고립감이 불안감을 증폭시키고 있네요.","sourceDialogue":537,"category":"자아·성격","label":"Complex Reflection"},{"id":923,"text":"반응이나 질에 대한 고려 없이 자신의 생각을 표현하는 연습은 중요한 과정입니다.","sourceDialogue":534,"category":"자아·성격","label":"General"},{"id":924,"text":"반전을 찾고자 하는 의지가 있으신 것만으로도 상당한 용기가 있어 보입니다.","sourceDialogue":678,"category":"취업·진로","label":"Affirm"},{"id":925,"text":"밤이 되면 느끼는 그 걱정이 정말 커다란 부담으로 다가오겠군요.","sourceDialogue":193,"category":"정신건강","label":"Complex Reflection"},{"id":926,"text":"밤이 되면 생각이 더욱 복잡해져서 편안한 잠을 찾기 어려운 상황이시군요.","sourceDialogue":138,"category":"정신건강","label":"Complex Reflection"},{"id":927,"text":"버림받았다고 느낄 정도로 외로움이 크게 다가오시는군요.","sourceDialogue":18,"category":"정신건강","label":"Complex Reflection"},{"id":928,"text":"변화를 위한 조치에 대해 고민하고 계셔서 큰 발전이 이루어지고 있는 시기라 할 수 있겠군요.","sourceDialogue":406,"category":"자아·성격","label":"General"},{"id":929,"text":"변화를 추구하시려는 용기가 있으시네요. 정말 용기 있는 결정입니다.","sourceDialogue":807,"category":"학업·고시","label":"Affirm"},{"id":930,"text":"변화에 대한 생각이 마음 깊은 곳에서 울리고 있군요.","sourceDialogue":501,"category":"자아·성격","label":"Complex Reflection"},{"id":931,"text":"부담감을 줄이고자 하는 적극적인 의지가 느껴집니다.","sourceDialogue":840,"category":"학업·고시","label":"Affirm"},{"id":932,"text":"부담감이 실제로 어깨를 누르는 듯한 느낌을 주고 있군요.","sourceDialogue":113,"category":"정신건강","label":"Complex Reflection"},{"id":933,"text":"부정적인 감정을 드러내는 것에 대한 강한 거부감이 있으시고, 그로 인해 자신을 억제하게 됨을 느끼고 계시는군요.","sourceDialogue":423,"category":"자아·성격","label":"Complex Reflection"},{"id":934,"text":"부정적인 생각을 인식하려고 노력한다는 것이 중요한 접근 방법이 될 수 있습니다.","sourceDialogue":488,"category":"자아·성격","label":"General"},{"id":935,"text":"불안감을 이겨내려는 노력은 여전히 유지되고 계시군요.","sourceDialogue":431,"category":"자아·성격","label":"Complex Reflection"},{"id":936,"text":"불안을 관리하는 기술에 대해 알아보고자 하는 것은 자기 개발의 길을 모색하는 과정이시군요.","sourceDialogue":439,"category":"자아·성격","label":"General"},{"id":937,"text":"비교를 멈추려는 결심을 하신 것이 쉽지 않았을 텐데, 그 용기에 박수를 보냅니다.","sourceDialogue":738,"category":"취업·진로","label":"Affirm"},{"id":938,"text":"사람과의 관계 형성에 대한 고민이 깊은 시간을 보내고 계시네요.","sourceDialogue":418,"category":"자아·성격","label":"Complex Reflection"},{"id":939,"text":"사람들과 어떻게 관계를 맺고 그 속에서 어떻게 하면 좋을지 고민이 깊으신 것 같아요.","sourceDialogue":224,"category":"대인관계","label":"General"},{"id":940,"text":"사람들과 어울리지 않으려는 노력이 오히려 혼자만의 시간을 더 찾게 만드는군요.","sourceDialogue":270,"category":"대인관계","label":"Complex Reflection"},{"id":941,"text":"사람들과의 관계에서 더 적극적이기를 원하시면서도 자신감이 부족하다고 느끼고 계시네요.","sourceDialogue":404,"category":"자아·성격","label":"Complex Reflection"},{"id":942,"text":"사람들과의 관계에서 적당한 거리를 유지하는 것이 부담스러우신가 보군요.","sourceDialogue":228,"category":"대인관계","label":"Complex Reflection"},{"id":943,"text":"사람이 많은 곳에서 느끼는 불안감이 증가하고 있네요.","sourceDialogue":529,"category":"자아·성격","label":"Complex Reflection"},{"id":944,"text":"사랑하는 사람들을 보호하려는 마음에서 자신의 진짜 모습을 숨기시는군요.","sourceDialogue":556,"category":"자아·성격","label":"Complex Reflection"},{"id":945,"text":"사회적 상황에서의 부담을 줄이기 위해 가능한 한 회피하려는 경향이 있으신 것 같네요.","sourceDialogue":271,"category":"대인관계","label":"Complex Reflection"},{"id":946,"text":"사회적 상황으로 인한 부담감이 커져 사람들과 멀어지고 계시는 경험이 무척 힘드실 것 같네요.","sourceDialogue":336,"category":"대인관계","label":"Complex Reflection"},{"id":947,"text":"삶에서 의미를 찾고자 하는 욕구가 근본적으로 중요한 부분인 것 같네요.","sourceDialogue":410,"category":"자아·성격","label":"Complex Reflection"},{"id":948,"text":"상대방과의 관계에서 이런 감정을 느끼시는 건 쉽지 않은 경험일 것입니다.","sourceDialogue":376,"category":"대인관계","label":"Complex Reflection"},{"id":949,"text":"상대방과의 솔직하고 편안한 대화를 통해 깊은 관계를 만들고 싶어하시는군요.","sourceDialogue":206,"category":"대인관계","label":"Complex Reflection"},{"id":950,"text":"상대방의 말에 귀 기울이고, 심도 깊은 관심을 나타내고자 하는 노력이 타인과의 관계에서 긍정적인 변화를 가져올 수 있겠네요.","sourceDialogue":265,"category":"대인관계","label":"Complex Reflection"},{"id":951,"text":"상처 주었던 사람들에 대한 감정 정리와 함께 다음 단계로 나아가는 방향을 찾는 것에 고민이 많으시군요.","sourceDialogue":70,"category":"정신건강","label":"Complex Reflection"},{"id":952,"text":"상처받은 감정을 다루고 싶지만, 어떻게 해야 할지 방향을 찾지 못하고 계시는군요.","sourceDialogue":971,"category":"가족","label":"Complex Reflection"},{"id":953,"text":"상호작용 과정에서 상대방에게 부담을 주는 것 같아 불편함을 느끼시는군요.","sourceDialogue":458,"category":"자아·성격","label":"Complex Reflection"},{"id":954,"text":"상황을 개선해보고자 하는 의지가 마음속에 자리 잡고 있네요.","sourceDialogue":50,"category":"정신건강","label":"Complex Reflection"},{"id":955,"text":"새 환경에 적응하는 데 있어 자신만의 속도가 필요하다고 느끼시는군요.","sourceDialogue":484,"category":"자아·성격","label":"Complex Reflection"},{"id":956,"text":"새로운 곳에서 일을 시작하면 누구나 불안하고 걱정이 커지는 법이죠.","sourceDialogue":346,"category":"대인관계","label":"General"},{"id":957,"text":"새로운 관계를 맺는 것이 꽤 부담되고 무서워하시는군요.","sourceDialogue":293,"category":"대인관계","label":"Complex Reflection"},{"id":958,"text":"새로운 방법을 시도하려는 용기를 내시는 것, 정말 멋진 결정이십니다.","sourceDialogue":688,"category":"취업·진로","label":"Affirm"},{"id":959,"text":"새로운 사람들과의 관계에서 두려움과 불안이 이전 경험들로 인해 더 커져 있습니다.","sourceDialogue":349,"category":"대인관계","label":"Complex Reflection"},{"id":960,"text":"새로운 시작 앞에서 느끼시는 불안함과 방향을 잡지 못하는 걱정이 있네요.","sourceDialogue":41,"category":"정신건강","label":"Complex Reflection"},{"id":961,"text":"새로운 시작에 대한 두려움은 많은 사람들이 공유하는 감정입니다.","sourceDialogue":201,"category":"대인관계","label":"General"},{"id":962,"text":"새로운 일에 도전할 때 느끼는 부담감이 있었군요.","sourceDialogue":12,"category":"정신건강","label":"Complex Reflection"},{"id":963,"text":"새로운 취미를 통해 자신만의 즐거움을 찾아가시는 과정이 되길 바랍니다.","sourceDialogue":564,"category":"자아·성격","label":"General"},{"id":964,"text":"새로운 환경에서 요구되는 활동에 대한 부담감을 느끼시는군요.","sourceDialogue":484,"category":"자아·성격","label":"Complex Reflection"},{"id":965,"text":"새로운 환경에서의 불안감과 함께 소속감을 느끼고 싶은 마음이 교차하고 있군요.","sourceDialogue":240,"category":"대인관계","label":"Complex Reflection"},{"id":966,"text":"새롭고 예측할 수 없는 상황에서 특히 대중교통을 사용할 때, 불안과 긴장감이 가중되고 있음을 알게 되었습니다.","sourceDialogue":66,"category":"정신건강","label":"Complex Reflection"},{"id":967,"text":"생활 패턴을 바꾸고 싶다는 생각은 변화에 대한 첫걸음을 이미 내딛은 것과 같아요.","sourceDialogue":150,"category":"정신건강","label":"General"},{"id":968,"text":"생활 패턴이 뒤바뀌면서 많이 힘들어하시는군요.","sourceDialogue":409,"category":"자아·성격","label":"Complex Reflection"},{"id":969,"text":"선택에 대한 후회는 결정을 내릴 때 가지고 있던 정보와 생각이 시간이 지나면서 변했다는 것을 의미하죠.","sourceDialogue":746,"category":"취업·진로","label":"General"},{"id":970,"text":"선택의 과정에서 혼란을 느끼며, 자신의 진정한 원하는 바를 파악하는 데 어려움을 겪고 계시는군요.","sourceDialogue":403,"category":"자아·성격","label":"Complex Reflection"},{"id":971,"text":"세부 계획을 만드는 과정에서 스스로 해결책을 찾아가려는 모습이 보기 좋네요.","sourceDialogue":852,"category":"학업·고시","label":"Affirm"},{"id":972,"text":"소망하는 바를 이루기 위해 필요한 자신감을 가지고 계신 듯하네요.","sourceDialogue":828,"category":"학업·고시","label":"Affirm"},{"id":973,"text":"소중한 활동에 대한 애정을 가지고 새로운 시도를 모색하고 계시군요.","sourceDialogue":666,"category":"취업·진로","label":"Affirm"},{"id":974,"text":"소통에 대한 어려움을 겪고 계시면서, 혼자만의 시간을 선호하게 되셨군요.","sourceDialogue":111,"category":"정신건강","label":"Complex Reflection"},{"id":975,"text":"솔직함과 존중 사이에서 균형을 찾으려 하는군요.","sourceDialogue":211,"category":"대인관계","label":"Complex Reflection"},{"id":976,"text":"수업 시간에 혼자 앉아야 한다는 것이 외로움을 더 깊게 느끼게 하시는 것 같네요.","sourceDialogue":897,"category":"학업·고시","label":"Complex Reflection"},{"id":977,"text":"스스로를 긍정적으로 바라보려는 노력은 매우 의미 있는 접근이 될 수 있습니다.","sourceDialogue":827,"category":"학업·고시","label":"Complex Reflection"},{"id":978,"text":"스스로를 있는 그대로 받아들이는 과정이 진정한 자신감으로 이어지는 귀중한 발견이었군요.","sourceDialogue":324,"category":"대인관계","label":"Complex Reflection"},{"id":979,"text":"스스로에 대한 신뢰가 집중력을 유지하는 데 큰 역할을 할 수 있겠군요.","sourceDialogue":683,"category":"취업·진로","label":"Affirm"},{"id":980,"text":"스트레스가 많은 상황에서는 불안함이 특히 강하게 나타난다고 여겨지네요.","sourceDialogue":38,"category":"정신건강","label":"Complex Reflection"},{"id":981,"text":"스트레스와 불안을 관리하고 싶다는 생각이 점점 강해지고 있네요.","sourceDialogue":91,"category":"정신건강","label":"Complex Reflection"},{"id":982,"text":"시간이 지남에 따라 감정이 완화되기를 기대하시는군요.","sourceDialogue":457,"category":"자아·성격","label":"General"},{"id":983,"text":"시도하는 과정 자체가 중요한 발전을 의미합니다.","sourceDialogue":744,"category":"취업·진로","label":"Affirm"},{"id":984,"text":"시도해보려는 용기를 내시는 건 정말 중요한 단계입니다.","sourceDialogue":775,"category":"취업·진로","label":"Affirm"},{"id":985,"text":"시작의 첫 발을 떼는 것 자체가 부담되고 있음을 느끼시는군요.","sourceDialogue":547,"category":"자아·성격","label":"Complex Reflection"},{"id":986,"text":"신체적 안전을 지키면서 본인의 잠재력을 발휘할 수 있는 직업을 찾고자 하는 의지가 돋보입니다.","sourceDialogue":723,"category":"취업·진로","label":"Affirm"},{"id":987,"text":"실수를 줄이려는 목표를 세우신 것만으로도 충분히 가치 있는 행동입니다.","sourceDialogue":719,"category":"취업·진로","label":"Affirm"},{"id":988,"text":"실수를 통해 배울 수 있다는 생각으로 자연스러움을 되찾고자 하는 욕구가 있으시군요.","sourceDialogue":283,"category":"대인관계","label":"Complex Reflection"},{"id":989,"text":"실제 경험을 통해 해당 분야에 대한 이해를 높이려 하시는군요.","sourceDialogue":602,"category":"취업·진로","label":"Affirm"},{"id":990,"text":"실패를 경험으로 바라볼 준비가 되어 계시다니 용기 있는 결정이십니다.","sourceDialogue":800,"category":"취업·진로","label":"Affirm"},{"id":991,"text":"실패를 통한 발전을 찾아보고 싶은 마음이 강해 보입니다.","sourceDialogue":106,"category":"정신건강","label":"Complex Reflection"},{"id":992,"text":"실행으로 옮기는 것은 시간이 필요한 과정입니다.","sourceDialogue":308,"category":"대인관계","label":"General"},{"id":993,"text":"아이의 진정한 행복을 위해 멈추지 않고 탐색하고 계시는군요.","sourceDialogue":25,"category":"정신건강","label":"Complex Reflection"},{"id":994,"text":"악몽으로 인해 편안한 잠을 취하기가 어려우시군요.","sourceDialogue":149,"category":"정신건강","label":"Complex Reflection"},{"id":995,"text":"어떤 결정을 내려야 할지 고민하시며 특정 관계에 대한 미묘한 감정을 겪고 계시는군요.","sourceDialogue":301,"category":"대인관계","label":"Complex Reflection"},{"id":996,"text":"어떻게 해야 할지 모르는 상황 속에서도 변화를 고민하고 계시네요.","sourceDialogue":461,"category":"자아·성격","label":"Complex Reflection"},{"id":997,"text":"어려운 상황 속에서도 관계의 개선을 원하시는 용기가 있어 보이네요.","sourceDialogue":269,"category":"대인관계","label":"Complex Reflection"},{"id":998,"text":"어려움을 겪으시는 환경에서도 스스로를 무능하다고 생각하시는군요.","sourceDialogue":175,"category":"정신건강","label":"Complex Reflection"},{"id":999,"text":"어렸을 때부터 가지고 있던 습관이 최근에는 힘들게 느껴지는 군요.","sourceDialogue":122,"category":"정신건강","label":"Complex Reflection"},{"id":1000,"text":"엄마의 화를 직접적으로 향하면서 책임감을 느끼는 상황이 힘들어 보이네요.","sourceDialogue":295,"category":"대인관계","label":"Complex Reflection"}]
});